insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('life-roles-balance-wheel', 'Life Roles Balance Wheel', 'worksheet'::resource_kind, 'A wheel diagram where a client rates how balanced work, family, health and other life roles feel right now.', 'Use it to open a conversation about which roles are running on empty and what to shift first.', array['Adults']::text[], '20 minutes', 'The client rates satisfaction in six to eight roles — partner, parent, worker, friend, self-care and so on — on a scale from zero to ten, marks each on a spoke of the wheel, then connects the points. An uneven wheel becomes the starting point for talking about which roles are quietly being neglected and what the client is willing to change first. Bring it back in a later session to see what moved.', '[{"id": "f0", "type": "textarea", "label": "List the roles you want to rate (work, parent, partner, friend, health, and so on)"}, {"id": "f1", "type": "textarea", "label": "Which role scored the lowest, and what does that tell you?"}, {"id": "f2", "type": "textarea", "label": "Which role scored the highest, and what is going right there?"}, {"id": "f3", "type": "textarea", "label": "What is one small change you could make in the lowest-scoring role this week?"}, {"id": "f4", "type": "textarea", "label": "What would need to be true for the wheel to look more balanced?"}]'::jsonb, array['work-life balance', 'self-monitoring', 'goal setting']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('motivation-readiness-ruler', 'Motivation Readiness Ruler', 'worksheet'::resource_kind, 'A 0-10 scale a client marks twice, once for how important a change feels and once for how confident they feel making it.', 'Use it to locate exactly where ambivalence about a change is sitting so you can work there.', array['Adults', 'Teens']::text[], '10 minutes', 'The client marks importance and confidence separately on two zero-to-ten lines, then explains why the number is not one point lower — that answer holds their own reasons for change, which land better coming from them than from you. A low confidence score with high importance points straight at where to focus the next few sessions.', '[{"id": "f0", "type": "textarea", "label": "The change you are considering"}, {"id": "f1", "type": "textarea", "label": "How important does this change feel right now, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "Why is that number not one point lower?"}, {"id": "f3", "type": "textarea", "label": "How confident do you feel you could make this change, 0 to 10?"}, {"id": "f4", "type": "textarea", "label": "What would move that confidence number up by one point?"}]'::jsonb, array['motivational interviewing', 'ambivalence', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('cue-anchored-routine-sheet', 'Cue-Anchored Routine Sheet', 'worksheet'::resource_kind, 'Attaches a new habit to a routine the client already does automatically, rather than a fresh time slot.', 'Use it to make a new habit easier to start by borrowing momentum from an existing one.', array['Adults']::text[], 'One week', 'The client names a habit already running on autopilot — making coffee, brushing teeth, sitting down at a desk — and attaches the new behavior right after it: “after I pour my coffee, I will write down three tasks.” Anchoring to an existing cue removes the need to remember a new time, which is usually where habit plans fall apart. Review which anchors held and which need a different cue.', '[{"id": "f0", "type": "textarea", "label": "The new habit you want to build"}, {"id": "f1", "type": "textarea", "label": "An existing routine that happens reliably, every day"}, {"id": "f2", "type": "textarea", "label": "Your plan: “After I ___, I will ___”"}, {"id": "f3", "type": "textarea", "label": "What might interrupt this plan, and what is the backup?"}, {"id": "f4", "type": "textarea", "label": "How did the anchor hold up this week?"}]'::jsonb, array['habits', 'behavioral', 'goal setting']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('transition-readiness-checklist', 'Transition Readiness Checklist', 'worksheet'::resource_kind, 'Walks a client through the practical and emotional pieces of an upcoming life change before it arrives.', 'Use it to surface what a client has already prepared for a transition and what still needs attention.', array['Adults']::text[], '30 minutes', 'Useful ahead of a move, a job change, a divorce finalizing, a retirement or any date the client has been counting down to. The checklist separates practical items (paperwork, logistics, people to notify) from emotional ones (what they are grieving, what they are relieved to leave, who they will lean on) so neither gets crowded out by the other. Revisit it as the date gets closer.', '[{"id": "f0", "type": "textarea", "label": "What is changing, and when?"}, {"id": "f1", "type": "textarea", "label": "Practical steps still outstanding"}, {"id": "f2", "type": "textarea", "label": "What you expect to miss"}, {"id": "f3", "type": "textarea", "label": "What you expect to be relieved to leave behind"}, {"id": "f4", "type": "textarea", "label": "Who you can lean on in the first weeks after"}, {"id": "f5", "type": "textarea", "label": "One thing that would make the transition feel less abrupt"}]'::jsonb, array['transitions', 'life review', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('weekly-self-care-menu', 'Weekly Self-Care Menu', 'worksheet'::resource_kind, 'A client-built menu of restorative activities sorted by how much time and energy each one takes.', 'Use it to give a client options that fit a five-minute gap as well as a free afternoon.', array['Adults']::text[], '20 minutes', 'Self-care plans that only list big-ticket items — a spa day, a weekend away — rarely get used on an ordinary Tuesday. The client instead sorts activities into three columns by time cost: five minutes, thirty minutes, and a half day, so there is always something on the menu that fits the moment. Pin it somewhere visible and check in on which column gets used most.', '[{"id": "f0", "type": "textarea", "label": "Five-minute options"}, {"id": "f1", "type": "textarea", "label": "Thirty-minute options"}, {"id": "f2", "type": "textarea", "label": "Half-day options"}, {"id": "f3", "type": "textarea", "label": "What usually stops you from using this list?"}, {"id": "f4", "type": "textarea", "label": "Which column did you actually use this week?"}]'::jsonb, array['self-care', 'burnout', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('should-statements-audit', 'Should Statements Audit', 'cbt'::resource_kind, 'Lists the self-imposed ‘should’ rules a client is carrying and tests each one for whose voice it is in.', 'Use it to loosen rigid self-imposed rules that are driving guilt or resentment.', array['Adults', 'Teens']::text[], '20 minutes', '‘Should’ statements often turn out to be inherited rather than chosen — a parent’s standard, an old boss’s expectation, a cultural message never examined. The client lists their current shoulds, then for each one traces where it came from and rates how much it still serves them. A rule that scores low on ‘still serves me’ is a candidate for rewriting into a preference instead of a demand.', '[{"id": "f0", "type": "textarea", "label": "A ‘should’ statement you catch yourself using often"}, {"id": "f1", "type": "textarea", "label": "Where do you think this rule came from?"}, {"id": "f2", "type": "textarea", "label": "What happens inside you when you break this rule?"}, {"id": "f3", "type": "textarea", "label": "How well does this rule actually serve you now, and why?"}, {"id": "f4", "type": "textarea", "label": "Rewrite it as a preference rather than a demand"}]'::jsonb, array['thinking traps', 'core beliefs', 'self-criticism']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('prediction-accuracy-tracker', 'Prediction Accuracy Tracker', 'cbt'::resource_kind, 'A running log comparing what a client predicted would happen against what actually happened.', 'Use it to build evidence, one entry at a time, that anxious predictions overstate the odds.', array['Adults', 'Teens']::text[], 'Ongoing', 'Before a feared situation, the client writes down the specific prediction and how certain they feel of it. Afterward they log what actually happened and re-rate their certainty. Kept over a few weeks, the pattern usually does more to shift belief than any single conversation could, because the client is looking at their own track record rather than taking your word for it.', '[{"id": "f0", "type": "textarea", "label": "The situation you are about to face"}, {"id": "f1", "type": "textarea", "label": "Your specific prediction"}, {"id": "f2", "type": "textarea", "label": "How certain are you, 0 to 100 percent?"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "Was your prediction right, partly right, or wrong?"}]'::jsonb, array['behavioral experiment', 'anxiety', 'evidence log']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('selective-attention-log', 'Selective Attention Log', 'cbt'::resource_kind, 'Tracks moments a client noticed only the negative in a situation that also held neutral or positive evidence.', 'Use it to show a client what their attention is filtering out, not just what it lets through.', array['Adults', 'Teens']::text[], '10 minutes', 'After a hard moment, the client writes down what they noticed first, then goes back and lists what else was actually present — a compliment that got skipped past, a thing that went fine, a neutral fact read as bad news. The point is not that the negative did not happen, but that attention narrowed around it. Over several entries, a pattern of what the filter tends to catch usually shows up.', '[{"id": "f0", "type": "textarea", "label": "The moment and what you noticed first"}, {"id": "f1", "type": "textarea", "label": "What else was actually present that you skipped past"}, {"id": "f2", "type": "textarea", "label": "Why do you think your attention went where it did?"}, {"id": "f3", "type": "textarea", "label": "What would you notice first if you were in a good mood?"}]'::jsonb, array['thinking traps', 'self-monitoring', 'core CBT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('core-belief-timeline', 'Core Belief Timeline', 'cbt'::resource_kind, 'Maps when a long-held belief about the self first took shape and what has fed it since.', 'Use it to trace a core belief back to its origin instead of treating it as simply true.', array['Adults']::text[], '30 minutes', 'The client draws a line from childhood to now and marks moments that seem to have built the belief — an early message, a repeated comparison, a formative event — alongside moments that contradicted it and got waved away. Seeing the belief as something assembled over time, rather than a fact about them, is often the first crack in it. Pair with ongoing evidence-gathering work.', '[{"id": "f0", "type": "textarea", "label": "The core belief you are examining"}, {"id": "f1", "type": "textarea", "label": "The earliest moment you can trace it to"}, {"id": "f2", "type": "textarea", "label": "Other moments along the way that reinforced it"}, {"id": "f3", "type": "textarea", "label": "Moments that contradicted it — what happened to those?"}, {"id": "f4", "type": "textarea", "label": "Whose voice does this belief sound like?"}]'::jsonb, array['core beliefs', 'schema', 'self-esteem']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('graded-task-ladder', 'Graded Task Ladder', 'cbt'::resource_kind, 'Breaks one overwhelming task into small enough steps that the first one is almost too easy to skip.', 'Use it to get a stalled task moving again by lowering the size of the first step, not the standard.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names the task that has been avoided, then works backward to a first step small enough to complete in under five minutes — opening the document, not writing the report. Each rung of the ladder should feel only slightly harder than the one before it. Momentum, not motivation, is the target: the ladder exists to be climbed on a day motivation is nowhere in sight.', '[{"id": "f0", "type": "textarea", "label": "The task you have been avoiding"}, {"id": "f1", "type": "textarea", "label": "Step 1 — small enough to do in under five minutes"}, {"id": "f2", "type": "textarea", "label": "Step 2"}, {"id": "f3", "type": "textarea", "label": "Step 3"}, {"id": "f4", "type": "textarea", "label": "Step 4"}, {"id": "f5", "type": "textarea", "label": "What will you do right after finishing step 1, to keep going?"}]'::jsonb, array['procrastination', 'behavioral activation', 'task initiation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('tug-of-war-with-the-monster', 'Tug-of-War With the Monster', 'act'::resource_kind, 'A classic ACT metaphor sheet: pulling harder against a painful feeling only pulls the client closer to it.', 'Use it to introduce the idea that dropping the rope, not winning, is what loosens a struggle.', array['Adults', 'Teens']::text[], '15 minutes', 'The client pictures a tug-of-war against a monster representing an unwanted feeling, with a pit between them. Pulling harder does not create distance — it only tightens the rope. The move that changes anything is dropping the rope altogether, which does not make the monster disappear but ends the exhausting pull. Use it to open a conversation about where a client keeps pulling instead of dropping the rope.', '[{"id": "f0", "type": "textarea", "label": "What is the monster on the other end of your rope?"}, {"id": "f1", "type": "textarea", "label": "How hard have you been pulling, and for how long?"}, {"id": "f2", "type": "textarea", "label": "What has pulling harder actually gotten you?"}, {"id": "f3", "type": "textarea", "label": "What would dropping the rope look like this week?"}]'::jsonb, array['metaphor', 'acceptance', 'struggle']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('raisin-moment-practice', 'Raisin Moment Practice', 'act'::resource_kind, 'A short sensory exercise, noticing one small object fully, used to teach present-moment attention.', 'Use it to give a client a concrete, repeatable way to practice noticing rather than thinking about.', array['Adults', 'Teens', 'Groups']::text[], 'Ten minutes', 'The client spends a few slow minutes with one small object — a raisin, a coin, a leaf — noticing texture, weight, smell and sound before doing anything else with it. The exercise is not about the object; it is a rehearsal for bringing that same quality of attention to a meal, a conversation or a walk later. Debrief what pulled attention away and how many times it was brought back.', '[{"id": "f0", "type": "textarea", "label": "The object you practiced with"}, {"id": "f1", "type": "textarea", "label": "What did you notice that you would normally miss?"}, {"id": "f2", "type": "textarea", "label": "How many times did your mind wander, and to where?"}, {"id": "f3", "type": "textarea", "label": "Where else could you practice this kind of attention this week?"}]'::jsonb, array['mindfulness', 'present moment', 'core ACT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('values-versus-goals-sorter', 'Values Versus Goals Sorter', 'act'::resource_kind, 'Sorts a client’s list of ‘things I want’ into values, which are directions, and goals, which are destinations.', 'Use it to separate an ongoing direction from a one-time finish line so values survive an unmet goal.', array['Adults', 'Teens']::text[], '20 minutes', 'A goal can be reached and closed — get the job, finish the degree. A value cannot, because it is a direction rather than a destination, like ‘being a supportive parent.’ The client sorts their list into the two columns and, for each goal, names the value underneath it. When a goal falls through, the value is still there to act on, which keeps a setback from feeling like the whole thing collapsed.', '[{"id": "f0", "type": "textarea", "label": "List the things you have been striving for"}, {"id": "f1", "type": "textarea", "label": "Sort each into Goal (can be finished) or Value (ongoing direction)"}, {"id": "f2", "type": "textarea", "label": "For each goal, what value sits underneath it?"}, {"id": "f3", "type": "textarea", "label": "If this goal fell through tomorrow, how could you still act on the value?"}]'::jsonb, array['values', 'goal setting', 'core ACT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('cost-of-control-log', 'Cost of Control Log', 'act'::resource_kind, 'Tracks what a client gives up each time they work hard to avoid or control an unwanted feeling.', 'Use it to add up the real cost of control efforts that have not actually worked.', array['Adults']::text[], 'Ongoing', 'Every time a client cancels a plan, avoids a conversation or numbs out to keep a feeling away, something else gets spent — time, a relationship, a step toward something that mattered. The log tracks the control effort and its price side by side. Over several entries the total cost usually becomes more persuasive than any argument that the avoidance is not working.', '[{"id": "f0", "type": "textarea", "label": "What you did to avoid or control the feeling"}, {"id": "f1", "type": "textarea", "label": "The feeling you were trying to avoid"}, {"id": "f2", "type": "textarea", "label": "What did it cost you — time, a relationship, an opportunity?"}, {"id": "f3", "type": "textarea", "label": "Did the feeling actually go away, or come back?"}]'::jsonb, array['acceptance', 'avoidance', 'workability']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('values-aligned-weekly-planner', 'Values-Aligned Weekly Planner', 'act'::resource_kind, 'A weekly planner where each scheduled block gets tagged with the value it serves.', 'Use it to make values visible in an ordinary week instead of living only as a list.', array['Adults']::text[], 'One week', 'Alongside the usual weekly grid, each planned block gets a one-word tag naming the value it moves toward — connection, health, creativity, and so on. At the end of the week the client can see which values actually got time and which stayed on paper only. It is less a productivity tool than a mirror on where a week’s hours actually went.', '[{"id": "f0", "type": "textarea", "label": "Your top three to five values right now"}, {"id": "f1", "type": "textarea", "label": "This week’s planned blocks and the value each one serves"}, {"id": "f2", "type": "textarea", "label": "Which value got the least time this week?"}, {"id": "f3", "type": "textarea", "label": "One block you could add next week for that value"}]'::jsonb, array['values', 'committed action', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('building-mastery-activity-log', 'Building Mastery Activity Log', 'dbt'::resource_kind, 'Logs one activity a day that builds a sense of competence, chosen slightly harder than what feels easy.', 'Use it to build emotional resilience through a steady sense that hard things are possible.', array['Adults', 'Teens']::text[], 'Ongoing', 'Building mastery is the DBT emotion regulation skill of doing something that takes real effort and doing it well, on purpose, to build a reserve of confidence before it is needed. The client picks one activity a day slightly harder than their comfort level and logs it along with how it felt to complete. Pick activities that are genuinely achievable — mastery, not failure, is the point.', '[{"id": "f0", "type": "textarea", "label": "Today’s mastery activity"}, {"id": "f1", "type": "textarea", "label": "Why is this slightly harder than easy for you?"}, {"id": "f2", "type": "textarea", "label": "How did it feel to complete it?"}, {"id": "f3", "type": "textarea", "label": "What will tomorrow’s activity be?"}]'::jsonb, array['emotion regulation', 'building mastery', 'skills']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-before-acting-card', 'Pros and Cons Before Acting Card', 'dbt'::resource_kind, 'A DBT distress tolerance card weighing the pros and cons of tolerating a crisis versus acting on the urge.', 'Use it to slow a client down long enough to weigh both paths before either one is taken.', array['Adults', 'Teens']::text[], 'Five minutes', 'In a crisis moment, weighing pros and cons on the spot rarely happens on its own. The card walks through four boxes filled out ahead of time and reread in the moment: the pros of tolerating the distress, the cons of tolerating it, the pros of acting on the urge, and the cons of acting on it. Reading all four before moving keeps the decision from being made on the first box alone.', '[{"id": "f0", "type": "textarea", "label": "The urge or crisis this card is for"}, {"id": "f1", "type": "textarea", "label": "Pros of tolerating the distress without acting"}, {"id": "f2", "type": "textarea", "label": "Cons of tolerating the distress without acting"}, {"id": "f3", "type": "textarea", "label": "Pros and cons of acting on the urge instead"}]'::jsonb, array['distress tolerance', 'crisis', 'skills']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('objectives-priorities-worksheet', 'Objectives Priorities Worksheet', 'dbt'::resource_kind, 'Has a client rank getting their objective, keeping the relationship and keeping self-respect before a hard conversation.', 'Use it to pick the right script before, not after, a conversation that could go several ways.', array['Adults', 'Teens']::text[], '15 minutes', 'Before a request or a boundary conversation, priorities are rarely equal: sometimes getting the outcome matters most, sometimes preserving the relationship does, sometimes it is walking away with self-respect intact. Ranking the three ahead of time changes how the conversation gets approached — pushing hard for an outcome reads differently than protecting a relationship above all. Use before scripting the actual conversation.', '[{"id": "f0", "type": "textarea", "label": "The conversation you are preparing for"}, {"id": "f1", "type": "textarea", "label": "Rank: getting the outcome, keeping the relationship, keeping self-respect"}, {"id": "f2", "type": "textarea", "label": "What does that ranking change about how you will approach it?"}, {"id": "f3", "type": "textarea", "label": "What would you be willing to give up to protect your top priority?"}]'::jsonb, array['interpersonal effectiveness', 'DEAR MAN', 'boundaries']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('willingness-versus-willfulness-sheet', 'Willingness Versus Willfulness Sheet', 'dbt'::resource_kind, 'Sorts a client’s recent responses to a hard reality into willing (working with it) and willful (fighting it).', 'Use it to show a client the difference between accepting a reality and giving up on changing it.', array['Adults']::text[], '20 minutes', 'Willingness is doing what the moment calls for, even reluctantly; willfulness is refusing to do what works because it feels unfair that it has to be done at all. Neither is about liking the situation. The client sorts a few recent responses to a hard reality into these two columns and looks at which one tends to move things forward and which tends to keep them stuck.', '[{"id": "f0", "type": "textarea", "label": "The hard reality you are responding to"}, {"id": "f1", "type": "textarea", "label": "A recent response that was willful (fighting it)"}, {"id": "f2", "type": "textarea", "label": "A recent response that was willing (working with it)"}, {"id": "f3", "type": "textarea", "label": "Which column tends to move things forward for you?"}]'::jsonb, array['radical acceptance', 'willingness', 'skills']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('riding-the-wave-practice', 'Riding the Wave Practice', 'dbt'::resource_kind, 'Tracks an intense emotion’s rise and fall to show a client that feelings peak and pass without action.', 'Use it to build tolerance for a feeling by watching it move rather than acting to make it stop.', array['Adults', 'Teens']::text[], '30 minutes', 'The client rates the intensity of a strong emotion every few minutes without doing anything to change it, plotting the numbers as the wave rises, peaks and comes back down. Most intense emotions pass within twenty to thirty minutes if nothing is done to prolong them. Seeing the actual shape of the wave on paper is often more convincing than being told the feeling will pass.', '[{"id": "f0", "type": "textarea", "label": "The emotion you are riding out, and what triggered it"}, {"id": "f1", "type": "textarea", "label": "Intensity at the start, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Intensity every five minutes after that"}, {"id": "f3", "type": "textarea", "label": "What did you notice about how the wave moved?"}]'::jsonb, array['emotion regulation', 'mindfulness', 'distress tolerance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('financial-values-conversation-guide', 'Financial Values Conversation Guide', 'couples'::resource_kind, 'Structured prompts for a couple to talk about what money means to each of them before talking numbers.', 'Use it to surface each partner’s money history before a budget conversation turns into a fight.', array['Couples']::text[], '30 minutes', 'Money fights are often values fights wearing a budget’s clothes — one partner equates saving with safety, the other equates spending with freedom, and neither realizes the other has a coherent logic. Each partner answers the prompts separately first, then reads answers aloud without interrupting. The goal of the first pass is understanding each other’s money story, not agreeing on a plan.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what did money mean in the home you grew up in?"}, {"id": "f1", "type": "textarea", "label": "Partner B: what did money mean in the home you grew up in?"}, {"id": "f2", "type": "textarea", "label": "Partner A: what does spending money on yourself feel like?"}, {"id": "f3", "type": "textarea", "label": "Partner B: what does spending money on yourself feel like?"}, {"id": "f4", "type": "textarea", "label": "One thing you learned about your partner’s money story"}]'::jsonb, array['Gottman', 'communication', 'money']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('in-law-boundaries-sheet', 'In-Law Boundaries Sheet', 'couples'::resource_kind, 'Has each partner name where extended family involvement feels supportive and where it feels intrusive.', 'Use it to get a couple presenting a united front to extended family instead of negotiating in front of them.', array['Couples']::text[], '20 minutes', 'Conflict about in-laws usually hides an unresolved question about which family unit comes first now. Each partner separately marks where extended family involvement feels welcome and where it crosses a line, then the two compare lists and draft one shared boundary to bring to the family together — never one partner enforcing it against the other’s relative alone.', '[{"id": "f0", "type": "textarea", "label": "Partner A: where does extended family involvement feel supportive?"}, {"id": "f1", "type": "textarea", "label": "Partner A: where does it feel intrusive?"}, {"id": "f2", "type": "textarea", "label": "Partner B: where does extended family involvement feel supportive?"}, {"id": "f3", "type": "textarea", "label": "Partner B: where does it feel intrusive?"}, {"id": "f4", "type": "textarea", "label": "One boundary you will hold together, as a team"}]'::jsonb, array['boundaries', 'family', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('desire-discrepancy-conversation-guide', 'Desire Discrepancy Conversation Guide', 'couples'::resource_kind, 'A low-pressure structure for a couple with mismatched desire to talk about it without either partner feeling blamed.', 'Use it to open a stuck conversation about differing desire without it turning into a scorecard.', array['Couples']::text[], 'Full session', 'Mismatched desire is one of the more avoided couples topics because it so easily turns into blame in either direction. The guide has each partner describe what desire feels tied to for them — connection, stress, body image, timing — before either one raises frequency at all, so the conversation starts with understanding instead of a number. Best run in session first before being sent home.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what does feeling desired usually depend on for you?"}, {"id": "f1", "type": "textarea", "label": "Partner B: what does feeling desired usually depend on for you?"}, {"id": "f2", "type": "textarea", "label": "What gets in the way most often for each of you?"}, {"id": "f3", "type": "textarea", "label": "One thing each partner could do that would help, without pressure"}]'::jsonb, array['intimacy', 'communication', 'Gottman']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('blended-family-roles-sheet', 'Blended Family Roles Sheet', 'couples'::resource_kind, 'Has each adult in a blended family name what role they are actually playing versus what they assumed they would.', 'Use it to make unspoken assumptions about a stepparent’s role explicit before they cause conflict.', array['Couples', 'Adults']::text[], '30 minutes', 'Stepparent role confusion — disciplinarian, friend, bystander — is a common source of blended-family friction, often because nobody ever agreed on it out loud. Each adult writes the role they think they are playing and the role they think the children see them playing; differences between those columns are usually where the tension lives. Bring the children’s perspective in separately when appropriate.', '[{"id": "f0", "type": "textarea", "label": "Adult 1: what role do you think you are playing day to day?"}, {"id": "f1", "type": "textarea", "label": "Adult 2: what role do you think you are playing day to day?"}, {"id": "f2", "type": "textarea", "label": "What role do you think the children actually see each of you in?"}, {"id": "f3", "type": "textarea", "label": "Where do those roles clash, and what would help?"}]'::jsonb, array['family', 'communication', 'boundaries']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('long-distance-connection-planner', 'Long-Distance Connection Planner', 'couples'::resource_kind, 'Helps a couple living apart schedule the kinds of connection that a shared home usually provides by default.', 'Use it to replace the incidental closeness of shared space with something deliberate.', array['Couples']::text[], '20 minutes', 'Couples sharing a home get connection almost by accident — a hallway conversation, a shared meal. Distance removes that, and video calls alone rarely replace it. The planner has the couple name specific kinds of connection they are missing — parallel activity, physical affection, daily check-ins, a plan for the next visit — and schedule a concrete way to approximate each one.', '[{"id": "f0", "type": "textarea", "label": "What kind of closeness do you miss most from being together?"}, {"id": "f1", "type": "textarea", "label": "One way you could approximate it this week, apart"}, {"id": "f2", "type": "textarea", "label": "How often will you check in, and how?"}, {"id": "f3", "type": "textarea", "label": "When is your next time together, and what will you protect for it?"}]'::jsonb, array['connection', 'rituals', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('friendship-skills-practice-cards', 'Friendship Skills Practice Cards', 'kids'::resource_kind, 'Role-play cards a parent and child act out together, practicing one small friendship skill at a time.', 'Use it to rehearse a specific social skill in a low-stakes setting before the child needs it at school.', array['Children']::text[], '15 minutes', 'Each card names one small scenario — joining a game already in progress, handling being left out, taking a turn — and the parent role-plays it with the child, switching roles so the child gets to practice both sides. Keep each round short and end on one the child pulled off well. The parent notes which scenarios still feel hardest so those get more practice.', '[{"id": "f0", "type": "textarea", "label": "Which scenario did you practice today?"}, {"id": "f1", "type": "textarea", "label": "What did you try saying or doing?"}, {"id": "f2", "type": "textarea", "label": "What felt easy about it?"}, {"id": "f3", "type": "textarea", "label": "What felt hard about it?"}, {"id": "f4", "type": "textarea", "label": "Parent: which scenario should you practice again next time?"}]'::jsonb, array['social skills', 'children', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('growth-mindset-garden-craft', 'Growth Mindset Garden Craft', 'kids'::resource_kind, 'A child plants a paper garden where mistakes become seeds that grow into things learned.', 'Use it to give a young perfectionist a hands-on way to see a mistake as the start of something, not an ending.', array['Children']::text[], '20 minutes', 'The child draws or cuts out a garden bed and, each time a mistake comes up in session or at home, adds a paper seed labeled with what the mistake was. Over following sessions, seeds that the child has learned something from get a flower drawn on top. The garden grows messier before it grows prettier, which is the point: mistakes are what the garden is made of, not weeds pulled out of it.', '[{"id": "f0", "type": "textarea", "label": "What mistake will you plant as a seed today?"}, {"id": "f1", "type": "textarea", "label": "What did this mistake teach you?"}, {"id": "f2", "type": "textarea", "label": "Which seeds in your garden have grown into flowers?"}, {"id": "f3", "type": "textarea", "label": "Parent: which seed are you proud of your child for planting?"}]'::jsonb, array['perfectionism', 'children', 'growth mindset']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('family-feelings-check-in-chart', 'Family Feelings Check-In Chart', 'kids'::resource_kind, 'A visual chart the whole family uses at dinner to name one feeling each, in a few words or a color.', 'Use it to normalize naming feelings out loud as an ordinary family habit, not a special occasion.', array['Children', 'Adults']::text[], 'Five minutes daily', 'Posted somewhere the family gathers, the chart gives everyone — parents included — a fast way to name a feeling with a word or a color rather than a full explanation. A rule of no follow-up questions unless the person offers more keeps it low-pressure enough that kids keep using it. Over time it becomes easier for a child to bring up a harder feeling because naming small ones is already routine.', '[{"id": "f0", "type": "textarea", "label": "Today’s feeling, in one word or color: Family Member 1"}, {"id": "f1", "type": "textarea", "label": "Today’s feeling, in one word or color: Family Member 2"}, {"id": "f2", "type": "textarea", "label": "Today’s feeling, in one word or color: Family Member 3"}, {"id": "f3", "type": "textarea", "label": "Did anyone want to say more about theirs?"}]'::jsonb, array['emotion identification', 'family', 'routines']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('team-family-motto-poster', 'Team Family Motto Poster', 'kids'::resource_kind, 'The family designs and decorates a shared motto that names how they want to treat each other.', 'Use it to give a family a shared, visible reminder they helped write themselves.', array['Children', 'Adults']::text[], '30 minutes', 'Rather than a rule handed down, the family brainstorms together what they want to be known for — ‘we try again’, ‘we listen first’ — and votes on a short motto everyone had a hand in. Decorating and posting it somewhere visible matters as much as the words: a motto the kids helped design gets referenced far more often than a poster of house rules that arrived already finished.', '[{"id": "f0", "type": "textarea", "label": "What words or phrases did each person suggest?"}, {"id": "f1", "type": "textarea", "label": "Which one did the family choose, and why?"}, {"id": "f2", "type": "textarea", "label": "How will you decorate the poster?"}, {"id": "f3", "type": "textarea", "label": "Where will it go, and who will remind the family to look at it?"}]'::jsonb, array['family', 'children', 'routines']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('sibling-peace-treaty-worksheet', 'Sibling Peace Treaty Worksheet', 'kids'::resource_kind, 'Siblings draft a simple, decorated agreement about how they will handle disagreements between them.', 'Use it to give siblings language for conflict that a parent did not write for them.', array['Children']::text[], '20 minutes', 'With a parent facilitating rather than dictating, siblings each name one thing that bothers them about fighting with the other and one thing they are willing to try differently. The ‘treaty’ gets written in the children’s own words and decorated like a real document, which gives it more weight than a verbal rule ever manages. Revisit and revise it as needed rather than treating it as final.', '[{"id": "f0", "type": "textarea", "label": "Sibling 1: what bothers you most about our fights?"}, {"id": "f1", "type": "textarea", "label": "Sibling 2: what bothers you most about our fights?"}, {"id": "f2", "type": "textarea", "label": "Sibling 1: one thing I will try differently"}, {"id": "f3", "type": "textarea", "label": "Sibling 2: one thing I will try differently"}, {"id": "f4", "type": "textarea", "label": "How will we handle it if the treaty gets broken?"}]'::jsonb, array['family', 'children', 'repair']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('strengths-bingo', 'Strengths Bingo', 'game'::resource_kind, 'A bingo card of character strengths where a group fills a square each time they spot that strength in someone.', 'Use it to get a group noticing and naming strengths in each other out loud.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Each square names a strength — patience, humor, honesty, creativity — and players mark it when they see a group member display it during the session or activity, then say so out loud before marking the square. It turns strength-spotting into something active rather than a static list, and the debrief usually surfaces strengths a member did not know others noticed in them.', '[{"id": "f0", "type": "textarea", "label": "Which square did you fill first, and who earned it?"}, {"id": "f1", "type": "textarea", "label": "Which strength did you notice in yourself today?"}, {"id": "f2", "type": "textarea", "label": "Which strength surprised you to hear named about you?"}, {"id": "f3", "type": "textarea", "label": "What was it like to be the one naming strengths out loud?"}]'::jsonb, array['strengths', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('scenario-freeze-frame', 'Scenario Freeze Frame', 'game'::resource_kind, 'A group acts out a hard scenario, freezes on cue, and the group discusses the character’s options from there.', 'Use it to practice recognizing choice points inside a conflict before it escalates further.', array['Groups', 'Teens']::text[], '30 minutes', 'Two group members act out a scenario — a disagreement, a tempting shortcut, a tense conversation — and the facilitator calls ‘freeze’ at a turning point. The group discusses what the character could do next and why, then the scene resumes with a chosen option played out. Freezing mid-scene, rather than only debriefing after, keeps the choice point concrete instead of abstract.', '[{"id": "f0", "type": "textarea", "label": "What scenario did you act out?"}, {"id": "f1", "type": "textarea", "label": "Where did the group call freeze, and what was happening?"}, {"id": "f2", "type": "textarea", "label": "What options did the group come up with?"}, {"id": "f3", "type": "textarea", "label": "Which option did you choose to play out, and how did it go?"}]'::jsonb, array['group', 'play', 'decisions']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('the-support-web-game', 'The Support Web Game', 'game'::resource_kind, 'A group passes a ball of yarn while naming someone who supports them, building a visible web of connection.', 'Use it to make a group’s web of support visible and concrete rather than an idea talked about.', array['Groups']::text[], '20 minutes', 'Standing in a circle, each person holds the string, names a person or source of support in their life, and tosses the ball to someone else while keeping hold of their strand — building a literal web across the group. The debrief looks at how tangled and connected the web became, and what it felt like to be one strand holding the others up. A classic group-therapy opener for talking about support networks.', '[{"id": "f0", "type": "textarea", "label": "Who or what did you name as support?"}, {"id": "f1", "type": "textarea", "label": "What did the web look like by the end?"}, {"id": "f2", "type": "textarea", "label": "What was it like to hold a strand that others depended on?"}, {"id": "f3", "type": "textarea", "label": "Who in your life outside this room could you add to your own web?"}]'::jsonb, array['support', 'group', 'connection']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('coping-skills-jeopardy', 'Coping Skills Jeopardy', 'game'::resource_kind, 'A quiz-style game where teams answer coping-skills questions across categories for points.', 'Use it to review a group’s coping skills vocabulary in a competitive, low-pressure format.', array['Groups', 'Teens']::text[], '30 minutes', 'Categories might include Grounding, Distress Tolerance, and Thinking Traps, with point values tied to difficulty. Teams buzz in to answer, and correct answers include a quick real example, not just the definition, so the game reinforces application rather than memorization. Works well as a mid-course review of skills covered so far.', '[{"id": "f0", "type": "textarea", "label": "Which category did your team pick first, and why?"}, {"id": "f1", "type": "textarea", "label": "A question your team got right — what was the skill?"}, {"id": "f2", "type": "textarea", "label": "A question your team missed — what is the right answer?"}, {"id": "f3", "type": "textarea", "label": "Which skill do you want to practice more after playing?"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('pass-the-story-coping-chain', 'Pass the Story Coping Chain', 'game'::resource_kind, 'A group builds one collaborative story, each person adding a line where the character uses a coping skill.', 'Use it to practice naming coping strategies out loud inside a low-pressure, playful format.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'One person starts a story with a character facing a stressful moment; each following person adds one line, and every third turn the added line has to include the character using a coping skill. The story usually gets funnier and stranger as it goes, which is part of the point — coping skills get rehearsed without the exercise feeling like a worksheet. Debrief which skills came up most.', '[{"id": "f0", "type": "textarea", "label": "What was the story about?"}, {"id": "f1", "type": "textarea", "label": "Which coping skills showed up in the story?"}, {"id": "f2", "type": "textarea", "label": "Which one would you actually use yourself?"}, {"id": "f3", "type": "textarea", "label": "What made this easier or harder than just listing skills?"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('orienting-to-now-practice', 'Orienting to Now Practice', 'worksheet'::resource_kind, 'A grounding worksheet that has a client name concrete present-day details to signal to the body that the danger has passed.', 'Use it to interrupt a flashback or a flooded moment by anchoring attention in the present.', array['Adults', 'Teens']::text[], 'Ten minutes', 'The client lists concrete facts that could only be true right now — today’s date, the room they are in, three things they can see — to help the body register that the present is not the past. Run it first in session so the client has felt it work before trying it alone. If distress escalates toward a crisis, the client’s safety plan and 988 (call or text) are the next step, not this worksheet.', '[{"id": "f0", "type": "textarea", "label": "Today’s date and where you are right now"}, {"id": "f1", "type": "textarea", "label": "Three things you can see around you"}, {"id": "f2", "type": "textarea", "label": "One thing that reminds you this is not then"}, {"id": "f3", "type": "textarea", "label": "How did your body feel before and after this practice?"}, {"id": "f4", "type": "textarea", "label": "If distress keeps rising, who or what do you turn to next?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('then-versus-now-thought-sort', 'Then Versus Now Thought Sort', 'cbt'::resource_kind, 'Sorts intrusive trauma-related thoughts into a ‘made sense then’ column and a ‘not true now’ column.', 'Use it to separate a survival belief that was accurate then from its accuracy now.', array['Adults', 'Teens']::text[], '20 minutes', 'Beliefs formed to survive a dangerous situation — ‘nobody is safe’, ‘I have to stay alert’ — made sense at the time and can outlast the danger. The client sorts current intrusive thoughts into what made sense then versus what is actually true now, without needing to describe the event itself. The sort itself, not the story behind it, is the therapeutic move.', '[{"id": "f0", "type": "textarea", "label": "A thought that shows up often"}, {"id": "f1", "type": "textarea", "label": "Made sense then — why?"}, {"id": "f2", "type": "textarea", "label": "True now — yes or no, and why?"}, {"id": "f3", "type": "textarea", "label": "What is actually true about your safety today?"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'psychoeducation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-alarm', 'Making Room for the Alarm', 'act'::resource_kind, 'An acceptance practice for making room for the body’s alarm sensations without fighting or fixing them.', 'Use it to reduce the added suffering that comes from fighting the body’s alarm response itself.', array['Adults', 'Teens']::text[], '15 minutes', 'Trauma often leaves the body’s alarm system primed to fire even when nothing dangerous is happening. Fighting the alarm — trying to force it off — tends to make it louder. The client practices making room for the sensation, breathing around it rather than against it, while doing one small values-aligned action anyway. No detail of the original event is needed for this practice to work.', '[{"id": "f0", "type": "textarea", "label": "Where do you notice the alarm in your body?"}, {"id": "f1", "type": "textarea", "label": "What is your usual move against it — fight, flee, numb?"}, {"id": "f2", "type": "textarea", "label": "Practice making room for it for one minute — what did you notice?"}, {"id": "f3", "type": "textarea", "label": "What is one small action you could still take with the alarm present?"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'grounding']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('paired-muscle-relaxation-for-hyperarousal', 'Paired Muscle Relaxation for Hyperarousal', 'dbt'::resource_kind, 'A brief muscle tension-and-release sequence used to bring down physical hyperarousal after a trauma trigger.', 'Use it to give the body a fast, physical off-ramp when hyperarousal has already taken over.', array['Adults', 'Teens']::text[], 'Ten minutes', 'When a trigger has already activated the body — racing heart, tight chest, restlessness — talking is often the wrong first move. The client tenses one muscle group hard for five seconds, then releases, moving through the body head to feet, pairing each release with a slow exhale. The physical shift usually needs to happen before any cognitive work can land. Practice it calm first, before it is needed in a spike.', '[{"id": "f0", "type": "textarea", "label": "Where in your body do you feel the activation first?"}, {"id": "f1", "type": "textarea", "label": "Rate the intensity before starting, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Which muscle groups did you tense and release?"}, {"id": "f3", "type": "textarea", "label": "Rate the intensity after, 0 to 10"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'regulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('trauma-informed-partner-support-plan', 'Trauma-Informed Partner Support Plan', 'couples'::resource_kind, 'A plan a couple builds together for what actually helps when one partner is triggered, made in a calm moment.', 'Use it to give a supporting partner a concrete plan instead of guessing what helps in the moment.', array['Couples']::text[], '30 minutes', 'Built when both partners are calm, this plan names what the triggered partner finds helpful — space, a specific phrase, physical touch or its absence — and what to avoid, such as pressing for details or minimizing. The supporting partner is not asked to understand the trauma itself, only to follow the plan the way it is written. Revisit and adjust the plan as the couple learns more about what helps.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps you most when you are triggered?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what makes it worse?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what do you need to hear or do to feel useful in that moment?"}, {"id": "f3", "type": "textarea", "label": "A phrase either of you can use to signal ‘I need the plan right now’"}]'::jsonb, array['PTSD and trauma', 'support', 'safety planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('anxiety-fuel-log', 'Anxiety Fuel Log', 'worksheet'::resource_kind, 'Tracks daily habits, sleep, caffeine, avoidance and reassurance-seeking, that tend to raise or lower anxiety.', 'Use it to find the everyday inputs a client can adjust rather than only the anxious thoughts.', array['Adults', 'Teens']::text[], 'One week', 'Anxiety is shaped by more than thoughts — sleep debt, caffeine, skipped meals and avoidance all raise the baseline. The client logs a few of these inputs alongside a daily anxiety rating for a week or two, then looks for the inputs that track most closely with the highs and lows. Small changes to inputs are often easier for a client to start with than changing the anxious thoughts directly.', '[{"id": "f0", "type": "textarea", "label": "Hours of sleep last night"}, {"id": "f1", "type": "textarea", "label": "Caffeine today"}, {"id": "f2", "type": "textarea", "label": "Any avoidance today, and of what?"}, {"id": "f3", "type": "textarea", "label": "Overall anxiety today, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What pattern are you starting to notice?"}]'::jsonb, array['anxiety', 'self-monitoring', 'psychoeducation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('what-if-ladder', 'What If Ladder', 'cbt'::resource_kind, 'Arranges a client’s catastrophic ‘what if’ thoughts from mild to most feared and tests each in turn.', 'Use it to work through a chain of anxious predictions instead of getting stuck on the worst one.', array['Adults', 'Teens']::text[], '20 minutes', 'Anxious thinking often runs a chain — ‘what if I’m late’ leads to ‘what if I get fired’ leads to ‘what if I lose everything’ — and the client’s attention snags on the worst link. Laying the chain out as a ladder lets each link get examined for how likely it actually is, one rung at a time, rather than reacting to the whole chain at once.', '[{"id": "f0", "type": "textarea", "label": "Your starting worry"}, {"id": "f1", "type": "textarea", "label": "What if that happens — then what?"}, {"id": "f2", "type": "textarea", "label": "What if that happens — then what?"}, {"id": "f3", "type": "textarea", "label": "How likely is the worst rung, realistically?"}, {"id": "f4", "type": "textarea", "label": "What would you actually do if the worst rung happened?"}]'::jsonb, array['anxiety', 'thinking traps', 'catastrophizing']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('worry-weather-forecast', 'Worry Weather Forecast', 'act'::resource_kind, 'Reframes anxious thoughts as changeable weather passing through, rather than a forecast of what will happen.', 'Use it to build distance from anxious thoughts by treating them as weather, not fact.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'The client names today’s ‘mental weather’ — stormy, foggy, clear with a few clouds — as a way of holding anxious thoughts lightly rather than as literal predictions. Weather always passes, which is the point: today’s storm is not tomorrow’s forecast. Use it as a quick daily check-in that builds defusion without needing a long exercise each time.', '[{"id": "f0", "type": "textarea", "label": "Today’s mental weather report"}, {"id": "f1", "type": "textarea", "label": "What thoughts came with that weather?"}, {"id": "f2", "type": "textarea", "label": "What would you do today even with this weather present?"}, {"id": "f3", "type": "textarea", "label": "How did the weather change by the end of the day?"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('anxiety-opposite-action-card', 'Anxiety Opposite Action Card', 'dbt'::resource_kind, 'Applies the DBT opposite action skill to anxiety by naming the urge to avoid and the opposite move.', 'Use it to interrupt avoidance before it has a chance to reinforce the anxiety further.', array['Adults', 'Teens']::text[], 'Ongoing', 'When the urge from anxiety does not fit the actual level of danger — a normal meeting, not a real threat — DBT’s opposite action skill has the client identify the avoidance urge and do the opposite, fully, with matching body language. Half-hearted opposite action tends not to work; the client practices approaching all the way in, not just partway.', '[{"id": "f0", "type": "textarea", "label": "The situation and the anxious urge to avoid"}, {"id": "f1", "type": "textarea", "label": "Does the urge actually fit the danger here?"}, {"id": "f2", "type": "textarea", "label": "The opposite action, described fully"}, {"id": "f3", "type": "textarea", "label": "How did it go when you did the opposite action all the way?"}]'::jsonb, array['anxiety', 'opposite action', 'emotion regulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('worry-backpack-unpacking-craft', 'Worry Backpack Unpacking Craft', 'kids'::resource_kind, 'A child draws a backpack full of worries, then ‘unpacks’ one at a time to decide which ones to carry today.', 'Use it to help a child sort worries into ones to carry and ones to set down for now.', array['Children']::text[], '20 minutes', 'The child draws or writes each worry as an item inside a backpack, then takes them out one at a time and sorts them into ‘carry today’ and ‘set down for now’ piles with the parent’s help. Not every worry needs solving in one sitting; the craft gives a child physical practice choosing which one gets attention right now. Keep the ‘set down’ worries somewhere to revisit later, not just dismissed.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry backpack — what worries are inside?"}, {"id": "f1", "type": "textarea", "label": "Pick one worry to unpack first — what is it?"}, {"id": "f2", "type": "textarea", "label": "Carry today or set down for now?"}, {"id": "f3", "type": "textarea", "label": "Parent: which worry will you check back in on tomorrow?"}]'::jsonb, array['anxiety', 'children', 'worry']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('low-energy-day-menu', 'Low-Energy Day Menu', 'worksheet'::resource_kind, 'A pre-planned list of very low-effort activities a client can turn to on the hardest, lowest-energy days.', 'Use it to have a plan ready before a low day arrives, when planning feels hardest.', array['Adults', 'Teens']::text[], '15 minutes', 'Depression tends to be worst exactly when the energy to make a plan is lowest, so the menu gets built on a better day for use on a worse one. Every item should take five minutes or less and require almost no decision-making — open the curtains, drink a glass of water, text one person a single emoji. The goal on a hard day is doing one item, not several.', '[{"id": "f0", "type": "textarea", "label": "Five very low-effort items for your menu"}, {"id": "f1", "type": "textarea", "label": "Where will you keep this list so you can find it on a bad day?"}, {"id": "f2", "type": "textarea", "label": "On a hard day, which item did you manage?"}, {"id": "f3", "type": "textarea", "label": "How did doing even that one thing change the day?"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('effort-versus-mood-log', 'Effort Versus Mood Log', 'cbt'::resource_kind, 'Tests the belief ‘I’ll do it once I feel like it’ by comparing outcomes when action came before mood.', 'Use it to challenge the assumption that motivation has to arrive before action can start.', array['Adults', 'Teens']::text[], 'One week', 'Depression often convinces a client that mood has to improve before action is possible, but the reverse is usually more reliable: action first, mood follows. The client logs a few activities attempted, noting whether they waited to feel like it first or acted anyway, and rates mood before and after either way. Most people find the ‘acted anyway’ entries score better than they expected.', '[{"id": "f0", "type": "textarea", "label": "The activity"}, {"id": "f1", "type": "textarea", "label": "Did you wait to feel like it, or act first?"}, {"id": "f2", "type": "textarea", "label": "Mood before, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Mood after, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What does this entry tell you about waiting for motivation?"}]'::jsonb, array['depression', 'behavioral activation', 'core CBT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-practice', 'Values in the Fog Practice', 'act'::resource_kind, 'Helps a client name one values-aligned action to take even while depression makes everything feel flat.', 'Use it to keep values-based action moving even when a client cannot access much feeling at all.', array['Adults', 'Teens']::text[], '20 minutes', 'Depression can flatten access to feeling, including the satisfaction that usually rewards action, which is why waiting to ‘want to’ rarely works. The client names a value that still matters even in the fog and picks one small action in that direction, doing it without expecting to feel much yet. The action counts whether or not it produces a feeling — feeling can catch up later.', '[{"id": "f0", "type": "textarea", "label": "A value that still matters, even now"}, {"id": "f1", "type": "textarea", "label": "One small action in that direction you could take today"}, {"id": "f2", "type": "textarea", "label": "Did you take the action? What happened?"}, {"id": "f3", "type": "textarea", "label": "Did you expect to feel something — did you?"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('emotional-numbing-check-in', 'Emotional Numbing Check-In', 'dbt'::resource_kind, 'A brief check-in for noticing emotional numbness and using one small sensory cue to reconnect.', 'Use it to interrupt numbness with a small, deliberate sensory anchor rather than forcing a feeling.', array['Adults', 'Teens']::text[], 'Five minutes', 'Depression sometimes shows up less as sadness than as numbness — nothing registers much at all. Rather than trying to force a feeling, the client uses one deliberate sensory input — cold water on the wrists, a strong scent, bright light — and simply notices whatever small response shows up, without judging it as too small to count. Track what tends to work over several tries.', '[{"id": "f0", "type": "textarea", "label": "What did numbness feel like today?"}, {"id": "f1", "type": "textarea", "label": "Which sensory cue did you try?"}, {"id": "f2", "type": "textarea", "label": "What, if anything, did you notice afterward?"}, {"id": "f3", "type": "textarea", "label": "Which cues seem to work best for you so far?"}]'::jsonb, array['depression', 'emotion regulation', 'self-soothing']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('pleasant-memory-trivia', 'Pleasant Memory Trivia', 'game'::resource_kind, 'A group game where members take turns sharing and guessing details of each other’s pleasant memories.', 'Use it to get a group actively recalling and sharing positive memories rather than only naming problems.', array['Groups']::text[], '20 minutes', 'Each member shares a brief pleasant memory without saying when or where it happened; the group asks yes-or-no questions to guess details, turning recall into an active game rather than a static list. Depression narrows access to positive memory, so practicing retrieval, even playfully, is the point, not just hearing the memory once. Debrief which memories were hardest to think of.', '[{"id": "f0", "type": "textarea", "label": "The pleasant memory you shared (briefly, for yourself)"}, {"id": "f1", "type": "textarea", "label": "What questions did the group ask to guess details?"}, {"id": "f2", "type": "textarea", "label": "How hard was it to think of a pleasant memory today?"}, {"id": "f3", "type": "textarea", "label": "What did you notice hearing others’ memories?"}]'::jsonb, array['depression', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('time-blindness-check-card', 'Time Blindness Check Card', 'cbt'::resource_kind, 'Compares a client’s time estimate for a task against the clock, building awareness of time blindness.', 'Use it to make the gap between estimated and actual time visible instead of assumed.', array['Adults', 'Teens']::text[], 'Ongoing', 'Many people with ADHD consistently misjudge how long tasks take, in either direction, without realizing it, a pattern often called time blindness. The client estimates a task’s length before starting, times it, and logs both. Seeing the actual gap over several entries is usually more convincing than being told to ‘plan better,’ and it gives concrete numbers to pad future estimates with.', '[{"id": "f0", "type": "textarea", "label": "The task"}, {"id": "f1", "type": "textarea", "label": "Your time estimate before starting"}, {"id": "f2", "type": "textarea", "label": "Actual time it took"}, {"id": "f3", "type": "textarea", "label": "How far off was your estimate?"}]'::jsonb, array['ADHD', 'time management', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('interest-based-values-bridge', 'Interest-Based Values Bridge', 'act'::resource_kind, 'Bridges a boring but necessary task to a value that actually matters, to help follow-through stick.', 'Use it when interest alone will not carry a task, by connecting it to something the client values.', array['Adults', 'Teens']::text[], '15 minutes', 'Motivation for many people with ADHD tracks interest more than importance, so a necessary-but-boring task can stall no matter how much it matters on paper. The client names the task, then traces a line to a value it actually serves — even a dull filing task can connect to ‘being someone people can rely on.’ The bridge will not make the task interesting, but it gives a reason worth returning to when attention drifts.', '[{"id": "f0", "type": "textarea", "label": "The boring task you keep avoiding"}, {"id": "f1", "type": "textarea", "label": "What value does finishing this actually serve?"}, {"id": "f2", "type": "textarea", "label": "How does it feel to name that connection?"}, {"id": "f3", "type": "textarea", "label": "What is the smallest next step toward it?"}]'::jsonb, array['ADHD', 'values', 'task initiation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('fidget-toolkit-planner', 'Fidget Toolkit Planner', 'kids'::resource_kind, 'A child tests a few fidget or movement tools and tracks which ones actually help them focus.', 'Use it to find which sensory tools genuinely help a child’s focus rather than guessing.', array['Children']::text[], 'One week', 'Not every fidget tool helps every child, and some become a distraction rather than a support. Over a week, the child tries a different tool each day — a squeeze ball, a standing option, a chewable, a doodle pad — during a homework or focus task, and rates with the parent how well it worked. The goal is a short list of two or three tools worth keeping on hand, not a full collection.', '[{"id": "f0", "type": "textarea", "label": "Today’s tool"}, {"id": "f1", "type": "textarea", "label": "What task were you using it during?"}, {"id": "f2", "type": "textarea", "label": "Did it help you focus? How much?"}, {"id": "f3", "type": "textarea", "label": "Parent: keep this tool on the list — yes or no?"}]'::jsonb, array['ADHD', 'children', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('attention-scavenger-hunt', 'Attention Scavenger Hunt', 'game'::resource_kind, 'A timed scavenger hunt game that rewards sustained visual attention rather than speed alone.', 'Use it to practice sustained attention in a format that feels like play, not a demand.', array['Children', 'Groups']::text[], '15 minutes', 'Players search a room or a picture for a list of hidden items within a time limit, then compare finds and talk about what helped them keep scanning versus what pulled their attention away. Because the challenge is built into the game rather than assigned as a task, sustained attention gets practiced without the usual resistance that comes with ‘focus on this.’ Debrief what strategies helped.', '[{"id": "f0", "type": "textarea", "label": "What items were you hunting for?"}, {"id": "f1", "type": "textarea", "label": "What helped you keep searching when it got hard?"}, {"id": "f2", "type": "textarea", "label": "What pulled your attention away?"}, {"id": "f3", "type": "textarea", "label": "What would help you focus even longer next time?"}]'::jsonb, array['ADHD', 'play', 'group']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('executive-function-support-agreement', 'Executive Function Support Agreement', 'couples'::resource_kind, 'A couple negotiates concrete ways one partner can support executive function without becoming a parent figure.', 'Use it to turn ‘just be more organized’ into specific, agreed support both partners are comfortable with.', array['Couples']::text[], '30 minutes', 'When one partner has ADHD, the other can drift into a caretaking or nagging role without either partner choosing it on purpose, which usually breeds resentment on both sides. The worksheet has each partner name specific supports that would actually help — a shared calendar, a standing reminder, first-refusal on reminders rather than repeated ones — and what would feel like being parented instead of supported.', '[{"id": "f0", "type": "textarea", "label": "ADHD partner: what kind of support actually helps you?"}, {"id": "f1", "type": "textarea", "label": "ADHD partner: what crosses into feeling like being parented?"}, {"id": "f2", "type": "textarea", "label": "Other partner: what would make offering support feel less exhausting?"}, {"id": "f3", "type": "textarea", "label": "One specific support you will both try this week"}]'::jsonb, array['ADHD', 'support', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-map', 'High-Risk Situation Map', 'worksheet'::resource_kind, 'Maps the places, people and times that tend to raise the risk of substance use, before they arrive.', 'Use it to plan around high-risk situations instead of relying on willpower in the moment.', array['Adults']::text[], '20 minutes', 'Urges rarely arrive at random — certain places, people, times of day or emotional states raise the odds substantially. The client maps their own pattern across these categories and, for each high-risk item, names one concrete plan: avoid it, bring support, or have an exit ready. The map becomes something to check before a risky weekend or event, not just an after-the-fact reflection.', '[{"id": "f0", "type": "textarea", "label": "Places that raise your risk"}, {"id": "f1", "type": "textarea", "label": "People that raise your risk"}, {"id": "f2", "type": "textarea", "label": "Times or situations that raise your risk"}, {"id": "f3", "type": "textarea", "label": "For your top risk, what is your plan?"}]'::jsonb, array['addiction', 'relapse prevention', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('urge-curve-prediction-sheet', 'Urge Curve Prediction Sheet', 'cbt'::resource_kind, 'Has a client predict, then track, how long an urge actually lasts to challenge the sense that it never will.', 'Use it to build evidence that urges peak and fall within a predictable window.', array['Adults']::text[], 'Ongoing', 'In the grip of an urge, it can feel permanent, which makes giving in seem like the only way out. Before it fades, the client predicts how long the urge will last; afterward they log the actual time. Most urges peak and fall within twenty to forty-five minutes if nothing is done to feed them. A few logged entries usually do more to shift the belief than being told urges pass.', '[{"id": "f0", "type": "textarea", "label": "What triggered the urge?"}, {"id": "f1", "type": "textarea", "label": "Predicted length of the urge"}, {"id": "f2", "type": "textarea", "label": "Actual length before it faded"}, {"id": "f3", "type": "textarea", "label": "What did you do while riding it out?"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('values-over-urges-card', 'Values Over Urges Card', 'act'::resource_kind, 'A pocket card linking one specific value to the moment an urge to use substances shows up.', 'Use it to give a client a values-based reason to reach for in the exact moment an urge appears.', array['Adults']::text[], 'Ten minutes', 'In the moment an urge appears, abstract commitments are hard to access, so the card keeps it concrete: one value, one reason it matters, written in the client’s own words, small enough to carry. The point is not to argue the urge away but to have something values-based ready to read in the ten seconds before a decision gets made either way.', '[{"id": "f0", "type": "textarea", "label": "The value you want on this card"}, {"id": "f1", "type": "textarea", "label": "Why does this value matter to you, in your own words?"}, {"id": "f2", "type": "textarea", "label": "Where will you keep this card?"}, {"id": "f3", "type": "textarea", "label": "Did you read it during an urge this week? What happened?"}]'::jsonb, array['addiction', 'values', 'urges']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('urge-distress-tolerance-menu', 'Urge Distress Tolerance Menu', 'dbt'::resource_kind, 'A menu of quick distress tolerance skills a client picks from specifically when an urge to use is strong.', 'Use it to have several fast options ready instead of one plan that might not fit the moment.', array['Adults']::text[], 'Ongoing', 'Not every distress tolerance skill fits every urge moment — sometimes intense sensation helps (TIPP), sometimes distraction does, sometimes it is simply calling someone. The client builds a short menu of their own best options ahead of time and picks whichever fits the moment an urge hits, rather than trying to remember a whole skill set under pressure.', '[{"id": "f0", "type": "textarea", "label": "Your top three to five go-to skills for an urge moment"}, {"id": "f1", "type": "textarea", "label": "Which one did you use this week?"}, {"id": "f2", "type": "textarea", "label": "Did it help — how much, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "Any skill to add or drop from the menu?"}]'::jsonb, array['addiction', 'distress tolerance', 'urges']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('supporting-without-enabling-worksheet', 'Supporting Without Enabling Worksheet', 'couples'::resource_kind, 'Helps a partner tell the difference between supportive help and behavior that enables continued substance use.', 'Use it to give a supporting partner concrete lines between helping and enabling.', array['Couples']::text[], 'Full session', 'Partners of someone working on substance use often want to help and are unsure where support turns into covering for, lending money toward, or minimizing continued use. Each partner separately lists actions that feel supportive and actions that feel like enabling, then the two compare lists together, ideally with the clinician present for the first pass rather than doing it alone at home.', '[{"id": "f0", "type": "textarea", "label": "Using partner: what kind of support actually helps you?"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what have you done that might be enabling?"}, {"id": "f2", "type": "textarea", "label": "What is one boundary the supporting partner needs to hold?"}, {"id": "f3", "type": "textarea", "label": "What support can continue without crossing into enabling?"}]'::jsonb, array['addiction', 'support', 'boundaries']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('anger-repair-timeline', 'Anger Repair Timeline', 'worksheet'::resource_kind, 'Tracks how long it actually takes to repair after an outburst, and what shortens or lengthens that time.', 'Use it to make the repair process itself, not just the outburst, something a client can improve.', array['Adults', 'Teens']::text[], 'Ongoing', 'An outburst is often treated as the whole event, but what happens in the hours and days after, an apology, a return to normal, rebuilt trust, matters just as much and is more within a client’s control. The client logs how long repair took after a recent episode and what specific action seemed to shorten it, building a record of what actually helps repair move faster next time.', '[{"id": "f0", "type": "textarea", "label": "The episode"}, {"id": "f1", "type": "textarea", "label": "What did you do to start repair, and when?"}, {"id": "f2", "type": "textarea", "label": "How long did it take before things felt normal again?"}, {"id": "f3", "type": "textarea", "label": "What seemed to speed up or slow down the repair?"}]'::jsonb, array['anger management', 'repair', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('fairness-assumption-check', 'Fairness Assumption Check', 'cbt'::resource_kind, 'Tests the ‘this is unfair’ thought that often sits underneath anger, against the actual facts available.', 'Use it to slow down the jump from perceived unfairness straight to an angry reaction.', array['Adults', 'Teens']::text[], '20 minutes', 'Anger often runs on an assumption of unfairness or a broken rule that felt certain in the moment but was never checked. The client writes the fairness assumption behind a recent angry moment, then lists what evidence actually supports it and what other explanation could also fit. This is not about deciding the client was wrong to be angry, only about slowing the jump from assumption to reaction.', '[{"id": "f0", "type": "textarea", "label": "The moment and the anger it triggered"}, {"id": "f1", "type": "textarea", "label": "What rule or fairness assumption felt broken?"}, {"id": "f2", "type": "textarea", "label": "What evidence actually supports that?"}, {"id": "f3", "type": "textarea", "label": "What is another explanation that could also fit?"}]'::jsonb, array['anger management', 'thinking traps', 'core beliefs']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('anger-wise-mind-pause-card', 'Anger Wise Mind Pause Card', 'dbt'::resource_kind, 'A pause card that walks a client from emotion mind toward wise mind in the middle of an anger spike.', 'Use it to interrupt the jump from trigger straight to reaction with one deliberate pause.', array['Adults', 'Teens']::text[], 'Five minutes', 'In an anger spike, emotion mind can take over fast, driving a reaction before wise mind gets a say. The card walks through a short sequence: notice the spike, name it as emotion mind, take one slow breath, and ask what wise mind would add to what emotion mind is saying. It will not stop the anger, but it buys the seconds needed for a choice instead of a reflex.', '[{"id": "f0", "type": "textarea", "label": "What triggered the spike?"}, {"id": "f1", "type": "textarea", "label": "What was emotion mind saying?"}, {"id": "f2", "type": "textarea", "label": "After the pause, what did wise mind add?"}, {"id": "f3", "type": "textarea", "label": "What did you do instead of the first reaction?"}]'::jsonb, array['anger management', 'wise mind', 'skills']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-countdown', 'Anger Thermometer Countdown', 'kids'::resource_kind, 'A thermometer chart where a child marks rising anger levels and picks a matching cool-down move at each one.', 'Use it to give a child a specific action tied to each level of anger, not just one plan for all of it.', array['Children']::text[], '20 minutes', 'Rather than one cool-down strategy for all of anger, the thermometer has a different move at each level — deep breaths at a low simmer, a break in another room at a rolling boil, telling a grown-up before it reaches the top. The child and parent build the chart together on a calm day, then practice recognizing which level they are at before choosing the matching move.', '[{"id": "f0", "type": "textarea", "label": "What does level 1 (a little annoyed) feel like in your body?"}, {"id": "f1", "type": "textarea", "label": "What move do you use at level 1?"}, {"id": "f2", "type": "textarea", "label": "What does level 3 (really mad) feel like?"}, {"id": "f3", "type": "textarea", "label": "What move do you use at level 3?"}, {"id": "f4", "type": "textarea", "label": "Parent: which level did you notice today, and did the move help?"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('cool-down-countdown-relay', 'Cool-Down Countdown Relay', 'game'::resource_kind, 'A relay game where each turn a player demonstrates a cool-down skill before passing to the next player.', 'Use it to rehearse quick cool-down skills as a group, in a format that stays playful, not preachy.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players take turns drawing a card naming a mild frustration and, before passing the turn along, demonstrating one cool-down skill on the spot — counting breaths, a shoulder shrug release, a short walk to a marker and back. Keeping it fast-paced and a little silly lowers the resistance kids and teens often have to anger skills practiced outside of an actual angry moment.', '[{"id": "f0", "type": "textarea", "label": "Which frustration card did you draw?"}, {"id": "f1", "type": "textarea", "label": "Which cool-down skill did you demonstrate?"}, {"id": "f2", "type": "textarea", "label": "Which skill from the game felt most natural to you?"}, {"id": "f3", "type": "textarea", "label": "Which one would you actually reach for when really angry?"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('certainty-seeking-cost-log', 'Certainty Seeking Cost Log', 'worksheet'::resource_kind, 'Logs how much time checking, researching or mentally reviewing actually costs in a day.', 'Use it to make the time cost of certainty-seeking visible instead of hidden inside a normal day.', array['Adults', 'Teens']::text[], 'One week', 'Checking, researching and mental reviewing can eat far more of a day than a client realizes because each instance feels small on its own. The log tracks time spent on these certainty-seeking behaviors across a day or two, then totals it up. Seeing the number in minutes or hours often does more to motivate change than a general sense that ‘it’s a lot.’', '[{"id": "f0", "type": "textarea", "label": "The certainty-seeking behavior"}, {"id": "f1", "type": "textarea", "label": "How long did it take?"}, {"id": "f2", "type": "textarea", "label": "Did it actually bring more certainty, or just relief that faded?"}, {"id": "f3", "type": "textarea", "label": "Total time today spent this way"}]'::jsonb, array['OCD', 'self-monitoring', 'checking']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('thought-action-fusion-check', 'Thought-Action Fusion Check', 'cbt'::resource_kind, 'Tests the belief that having a thought is as significant as acting on it, a common thread in intrusive thoughts.', 'Use it to separate the fact of having a thought from any claim about what it means.', array['Adults', 'Teens']::text[], '20 minutes', 'A thought crossing the mind and a thought reflecting intent or character are not the same thing, but intrusive thoughts can feel otherwise in the moment. The client writes the thought, then separately answers whether having it means they want it, and whether having it makes them a worse person. Most clients land on ‘having a thought is not the same as choosing it’ once it is laid out this plainly.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought"}, {"id": "f1", "type": "textarea", "label": "Does having this thought mean you want it to happen? Why or why not?"}, {"id": "f2", "type": "textarea", "label": "Does having it say something bad about your character? Why or why not?"}, {"id": "f3", "type": "textarea", "label": "What would you tell a friend who had this same thought?"}]'::jsonb, array['OCD', 'thinking traps', 'intrusive thoughts']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('sticky-thought-defusion-drill', 'Sticky Thought Defusion Drill', 'act'::resource_kind, 'A defusion drill for ‘sticky’ intrusive thoughts that keep returning no matter how often they are dismissed.', 'Use it to change a client’s relationship to a sticky thought rather than trying to make it stop.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Trying to push a sticky thought away tends to make it stick harder. The client instead practices noticing the thought and labeling it out loud — ‘I’m having the sticky thought that...’ — without arguing with it or trying to resolve it. The drill does not aim to make the thought go away; it aims to make having it feel less urgent and less like an emergency each time.', '[{"id": "f0", "type": "textarea", "label": "The sticky thought"}, {"id": "f1", "type": "textarea", "label": "Say it with the label: ‘I’m having the sticky thought that...’"}, {"id": "f2", "type": "textarea", "label": "What is your urge right after — to check, to argue, to avoid?"}, {"id": "f3", "type": "textarea", "label": "What did you do instead of following the urge?"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-practice-log', 'Uncertainty Tolerance Practice Log', 'dbt'::resource_kind, 'Logs small, deliberate practice sitting with uncertainty instead of resolving it through checking or reassurance.', 'Use it to build tolerance for not knowing, one small deliberate exposure at a time.', array['Adults', 'Teens']::text[], 'Ongoing', 'OCD tends to promise that one more check or one more reassurance will finally bring certainty, which keeps the cycle going. The client picks one small, low-stakes moment of uncertainty to leave unresolved on purpose — an unchecked lock, an unanswered what-if — and logs how the discomfort moved without the usual resolving behavior. Start small; the skill is tolerance, not bravado.', '[{"id": "f0", "type": "textarea", "label": "The uncertainty you left unresolved on purpose"}, {"id": "f1", "type": "textarea", "label": "Urge to check or seek reassurance, 0 to 10, at the start"}, {"id": "f2", "type": "textarea", "label": "How did the urge change over time without acting on it?"}, {"id": "f3", "type": "textarea", "label": "What did you learn from sitting with it?"}]'::jsonb, array['OCD', 'distress tolerance', 'uncertainty']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('sticky-thought-jar-craft', 'Sticky Thought Jar Craft', 'kids'::resource_kind, 'A child writes down sticky, repeating thoughts and puts them in a jar labeled ‘thoughts, not facts’.', 'Use it to give a child a physical way to set aside a sticky thought without needing to act on it.', array['Children']::text[], 'Ongoing', 'The child decorates a small jar and labels it ‘thoughts, not facts.’ When a sticky, repeating thought shows up, they write or draw it on a slip of paper and post it in the jar instead of checking, asking, or doing the thing the thought demands. The parent helps track how many slips go in the jar and celebrates moments a thought went in the jar instead of being acted on.', '[{"id": "f0", "type": "textarea", "label": "What sticky thought showed up today?"}, {"id": "f1", "type": "textarea", "label": "Did it go in the jar instead of being acted on?"}, {"id": "f2", "type": "textarea", "label": "How did it feel to let the thought sit in the jar?"}, {"id": "f3", "type": "textarea", "label": "Parent: how many slips went in the jar this week?"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('panic-symptom-reality-check-sheet', 'Panic Symptom Reality Check Sheet', 'worksheet'::resource_kind, 'Lists panic sensations next to what is actually happening in the body, to counter fear of imminent danger.', 'Use it to replace a catastrophic reading of panic symptoms with an accurate physiological one.', array['Adults', 'Teens']::text[], '20 minutes', 'A racing heart during panic can feel like a heart attack, and tight breathing can feel like suffocation, even though both are the body’s alarm system doing exactly what it is built to do. The sheet lists common panic sensations next to a plain explanation of what is actually happening physiologically. Reviewing it outside of an attack, when the fear is not active, helps it stick for use during one.', '[{"id": "f0", "type": "textarea", "label": "A panic sensation you experience"}, {"id": "f1", "type": "textarea", "label": "What does it feel like is happening?"}, {"id": "f2", "type": "textarea", "label": "What is actually happening in the body?"}, {"id": "f3", "type": "textarea", "label": "How does knowing that change the sensation’s intensity?"}]'::jsonb, array['panic attacks', 'psychoeducation', 'formulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('panic-attack-duration-tracker', 'Panic Attack Duration Tracker', 'cbt'::resource_kind, 'Tracks how long a panic attack actually lasts against how long it felt like it would last.', 'Use it to build evidence that panic attacks peak and pass within a predictable window.', array['Adults', 'Teens']::text[], 'Ongoing', 'In the middle of an attack, it can feel endless, which fuels the fear that drives it higher. The client notes the start time, the estimated feared duration, and the actual time it took to come back down. Most panic attacks peak within ten minutes and pass within twenty to thirty. A logged history of actual durations is often more convincing than being told this in the moment.', '[{"id": "f0", "type": "textarea", "label": "Start time"}, {"id": "f1", "type": "textarea", "label": "How long did it feel like it would last?"}, {"id": "f2", "type": "textarea", "label": "Actual time until it came back down"}, {"id": "f3", "type": "textarea", "label": "What helped it pass?"}]'::jsonb, array['panic attacks', 'self-monitoring', 'psychoeducation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('willing-passenger-panic-practice', 'Willing Passenger Panic Practice', 'act'::resource_kind, 'Practices letting panic sensations be present in the background while still doing a values-based activity.', 'Use it to keep panic sensations from automatically canceling a client’s plans.', array['Adults', 'Teens']::text[], '20 minutes', 'The instinct during panic is to stop everything until the sensations pass, which can end up shrinking a client’s life around avoiding the next attack. The practice has the client name one activity that matters and do it with the panic sensations present, treating them as an unwelcome passenger rather than the driver. The sensations are not fought or denied, just not obeyed as an order to stop.', '[{"id": "f0", "type": "textarea", "label": "The activity that matters to you"}, {"id": "f1", "type": "textarea", "label": "What sensations showed up while doing it?"}, {"id": "f2", "type": "textarea", "label": "Did you keep going anyway? What happened?"}, {"id": "f3", "type": "textarea", "label": "What did this practice teach you about the sensations’ actual power?"}]'::jsonb, array['panic attacks', 'acceptance', 'willingness']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('paced-exhale-panic-card', 'Paced Exhale Panic Card', 'dbt'::resource_kind, 'A breathing card with a longer exhale than inhale, used right at the first sign of a panic attack.', 'Use it to slow the body’s alarm response at the earliest moment an attack is building.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'A longer exhale than inhale signals the body’s calming system to engage, which can blunt a panic attack before it fully builds. The client practices a count of in for four, out for six, several times a day when calm so the pattern is already familiar, then reaches for it at the very first sign of an attack rather than waiting until it has taken over.', '[{"id": "f0", "type": "textarea", "label": "Practiced today, calm — how many rounds?"}, {"id": "f1", "type": "textarea", "label": "Did you notice early signs of an attack this week?"}, {"id": "f2", "type": "textarea", "label": "Did you use the breathing pattern? What happened?"}, {"id": "f3", "type": "textarea", "label": "How does the pattern feel different practiced calm versus in a spike?"}]'::jsonb, array['panic attacks', 'breathing', 'distress tolerance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('first-response-card-for-partners', 'First Response Card for Partners', 'couples'::resource_kind, 'A short, agreed script a partner uses in the first moments of noticing a panic attack starting.', 'Use it so a supporting partner has an agreed first move instead of improvising under pressure.', array['Couples']::text[], '20 minutes', 'The first response to a partner’s panic attack matters — some reactions help, others unintentionally add pressure (‘calm down,’ repeated questions). Built together outside of an attack, the card names the exact first move the supporting partner should make and a short phrase to say, agreed on in advance so neither partner is guessing in the moment.', '[{"id": "f0", "type": "textarea", "label": "Partner having attacks: what is genuinely helpful right at the start?"}, {"id": "f1", "type": "textarea", "label": "Partner having attacks: what makes it worse?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what will your first move be?"}, {"id": "f3", "type": "textarea", "label": "The agreed phrase you will say"}]'::jsonb, array['panic attacks', 'support', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('parent-battery-check', 'Parent Battery Check', 'worksheet'::resource_kind, 'Has a parent rate their own capacity before reacting, since the same behavior lands differently depending on it.', 'Use it to help a parent notice their own state before choosing a response, not just the child’s behavior.', array['Adults']::text[], 'Five minutes', 'The same misbehavior can get a very different response depending on how depleted the parent already is, which children usually cannot see and parents often do not track. Before responding to a flashpoint, the parent rates their own battery level and considers whether the plan they are about to use matches a low-battery day or assumes a full one. Sometimes the answer is simply to pause before responding at all.', '[{"id": "f0", "type": "textarea", "label": "Your battery level right now, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "What is happening with your child?"}, {"id": "f2", "type": "textarea", "label": "What response were you about to use?"}, {"id": "f3", "type": "textarea", "label": "Does that response fit your current battery level?"}]'::jsonb, array['parenting', 'self-monitoring', 'regulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('child-behavior-reframe-sheet', 'Child Behavior Reframe Sheet', 'cbt'::resource_kind, 'Tests a parent’s interpretation of a child’s behavior against other explanations that could also fit.', 'Use it to loosen an interpretation of a child’s behavior that is fueling a parent’s own anger.', array['Adults']::text[], '15 minutes', '‘He’s doing this on purpose’ and ‘she can’t handle this right now’ point to very different parental responses, even for the same behavior. The parent writes down their current read of a repeated frustrating behavior, then lists at least one other explanation that fits the facts equally well — a skill gap, an unmet need, a developmental stage. The goal is a wider set of options, not necessarily a kinder one.', '[{"id": "f0", "type": "textarea", "label": "The behavior"}, {"id": "f1", "type": "textarea", "label": "Your current interpretation of why they do it"}, {"id": "f2", "type": "textarea", "label": "One other explanation that fits equally well"}, {"id": "f3", "type": "textarea", "label": "Which interpretation would you rather respond from?"}]'::jsonb, array['parenting', 'thinking traps', 'core beliefs']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('parenting-values-compass-check', 'Parenting Values Compass Check', 'act'::resource_kind, 'Compares the parent a client wants to be with how they actually showed up in a recent hard moment.', 'Use it to close the gap between parenting values and a moment-to-moment reaction without shame.', array['Adults']::text[], '20 minutes', 'In a hard parenting moment, values are easy to lose track of under stress. The client names the kind of parent they want to be — patient, present, firm and warm — then looks honestly at a recent hard moment and how close it landed to that. The point is not guilt over the gap but using it to choose what to try differently next time, values still intact.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent you want to be, in a few words"}, {"id": "f1", "type": "textarea", "label": "A recent hard moment — what actually happened?"}, {"id": "f2", "type": "textarea", "label": "How close did that land to the parent you want to be?"}, {"id": "f3", "type": "textarea", "label": "What would help you close that gap next time?"}]'::jsonb, array['parenting', 'values', 'self-compassion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('parenting-team-huddle-sheet', 'Parenting Team Huddle Sheet', 'couples'::resource_kind, 'A short, regular check-in where co-parents align on approach before the next flashpoint, not during it.', 'Use it to get co-parents on the same page ahead of time instead of negotiating in front of the child.', array['Couples']::text[], 'Ten minutes', 'Disagreeing about parenting in front of a child undermines both parents and confuses the child about which rule holds. The huddle is a short, regular check-in, five minutes, not a summit, where co-parents name one upcoming flashpoint and agree on the approach in advance, so a united response is ready before the moment arrives rather than improvised during it.', '[{"id": "f0", "type": "textarea", "label": "An upcoming flashpoint you expect this week"}, {"id": "f1", "type": "textarea", "label": "Parent A’s usual approach to it"}, {"id": "f2", "type": "textarea", "label": "Parent B’s usual approach to it"}, {"id": "f3", "type": "textarea", "label": "The approach you are agreeing to use together"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('grown-up-and-me-feelings-match', 'Grown-Up and Me Feelings Match', 'kids'::resource_kind, 'A matching game where parent and child each guess what feeling fits a shared family moment from the week.', 'Use it to build a shared feelings vocabulary between parent and child through play, not lecture.', array['Children', 'Adults']::text[], '15 minutes', 'Parent and child each write down a few moments from the week on separate cards, then take turns guessing what feeling the other person had in that moment before comparing notes. Parents are often surprised by what a child actually felt, and children enjoy getting to ‘guess’ a grown-up’s feelings for once. Keep it playful; being wrong is part of the game, not a failure.', '[{"id": "f0", "type": "textarea", "label": "A moment from this week (child)"}, {"id": "f1", "type": "textarea", "label": "What feeling do you think the grown-up had? (child guesses)"}, {"id": "f2", "type": "textarea", "label": "A moment from this week (parent)"}, {"id": "f3", "type": "textarea", "label": "What feeling do you think the child had? (parent guesses)"}, {"id": "f4", "type": "textarea", "label": "What did you learn about each other’s feelings?"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('new-parent-reality-versus-expectation-sheet', 'New Parent Reality Versus Expectation Sheet', 'worksheet'::resource_kind, 'Compares what a new parent expected postpartum life to feel like against what it has actually been.', 'Use it to name the gap between expectation and reality without treating the gap as a personal failure.', array['Adults']::text[], '20 minutes', 'New-parent expectations are often shaped by curated images and other people’s highlight reels, and the gap between that and an actual postpartum reality can quietly feed shame. The client writes what they expected next to what has actually happened, in a few key areas — sleep, bonding, identity, support — and names the gap plainly rather than treating it as evidence something is wrong with them.', '[{"id": "f0", "type": "textarea", "label": "What did you expect this stage to feel like?"}, {"id": "f1", "type": "textarea", "label": "What has it actually felt like?"}, {"id": "f2", "type": "textarea", "label": "Where is the biggest gap?"}, {"id": "f3", "type": "textarea", "label": "What would help close that gap, even a little?"}]'::jsonb, array['perinatal and postpartum', 'expectations', 'self-compassion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('postpartum-guilt-thought-log', 'Postpartum Guilt Thought Log', 'cbt'::resource_kind, 'A thought log built around the specific guilt thoughts that show up often in the postpartum period.', 'Use it to examine postpartum guilt thoughts with the same rigor as any other automatic thought.', array['Adults']::text[], '15 minutes', '‘I should be enjoying this more’ and ‘a good parent wouldn’t feel this way’ are common postpartum automatic thoughts that rarely get the same scrutiny other anxious or depressive thoughts get, because they can feel like facts about being a bad parent. The client logs the thought, the evidence for and against it, and a more balanced alternative, the same way any other thought record works.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f2", "type": "textarea", "label": "Evidence against it"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}]'::jsonb, array['perinatal and postpartum', 'guilt', 'thinking traps']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-practice', 'Good Enough Parent Practice', 'act'::resource_kind, 'Practices holding a perfectionistic new-parent standard more lightly, in favor of a workable ‘good enough’.', 'Use it to loosen an all-or-nothing new-parent standard that is driving exhaustion or guilt.', array['Adults']::text[], '15 minutes', 'New parents often carry an unspoken standard of doing everything right, which nothing in an actual postpartum period can meet. The client names the standard, then practices noticing it as a thought — ‘I’m having the thought that a good parent would...’ — rather than a rule, and identifies what ‘good enough’ would actually look like today instead of the unreachable ideal.', '[{"id": "f0", "type": "textarea", "label": "The standard you are holding yourself to"}, {"id": "f1", "type": "textarea", "label": "Say it as a thought: ‘I’m having the thought that...’"}, {"id": "f2", "type": "textarea", "label": "What would ‘good enough’ look like today instead?"}, {"id": "f3", "type": "textarea", "label": "What gets easier if ‘good enough’ is actually enough?"}]'::jsonb, array['perinatal and postpartum', 'self-compassion', 'defusion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('postpartum-please-check', 'Postpartum PLEASE Check', 'dbt'::resource_kind, 'Adapts the DBT PLEASE skill to newborn care, where sleep and eating rarely follow a normal schedule.', 'Use it to track basic physical needs realistically, given what newborn care actually allows.', array['Adults']::text[], 'Five minutes', 'PLEASE, treating physical illness, eating, avoiding mood-altering substances, sleep and exercise, assumes a baseline that newborn care regularly disrupts, especially sleep. Rather than aiming for an ideal, the client tracks what was realistically possible each day and names one small thing that is actually within reach, given a newborn’s schedule, not an adult’s.', '[{"id": "f0", "type": "textarea", "label": "Sleep today — how much, in whatever pieces it came in"}, {"id": "f1", "type": "textarea", "label": "Did you eat something today? What?"}, {"id": "f2", "type": "textarea", "label": "Any physical symptoms you are ignoring?"}, {"id": "f3", "type": "textarea", "label": "One realistic thing you could add tomorrow, given the baby’s schedule"}]'::jsonb, array['perinatal and postpartum', 'PLEASE', 'vulnerability']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('postpartum-labor-rebalance-sheet', 'Postpartum Labor Rebalance Sheet', 'couples'::resource_kind, 'A concrete worksheet for rebalancing night wakings and household tasks after a birth, not just talking about it.', 'Use it to turn a vague ‘we should split things more evenly’ into a specific, written plan.', array['Couples']::text[], '20 minutes', 'Vague agreements to ‘share more’ tend to dissolve under exhaustion, while a specific written plan holds up better. The couple lists the recurring tasks of the newborn period — night wakings, feeding, household chores, outside support coordination — and assigns or alternates each one concretely, revisiting the plan every couple of weeks as things change fast in this period.', '[{"id": "f0", "type": "textarea", "label": "List the recurring tasks of this period"}, {"id": "f1", "type": "textarea", "label": "Who currently does most of each, and how does that feel?"}, {"id": "f2", "type": "textarea", "label": "How will you split or alternate each task going forward?"}, {"id": "f3", "type": "textarea", "label": "When will you revisit this plan?"}]'::jsonb, array['perinatal and postpartum', 'relationship issues', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('self-worth-sources-inventory', 'Self-Worth Sources Inventory', 'worksheet'::resource_kind, 'Inventories where a client’s current sense of worth comes from, and where they would rather it come from.', 'Use it to make an unexamined source of self-worth, often achievement or approval, visible and open to change.', array['Adults', 'Teens']::text[], '20 minutes', 'Self-worth quietly tied to performance, appearance or others’ approval tends to feel shaky, because all three can be taken away or withheld. The client lists what their worth currently seems to depend on, then names what they would rather it be grounded in instead — effort, values, character. The gap between the two lists becomes a direction to work toward, not a verdict on the client.', '[{"id": "f0", "type": "textarea", "label": "What does your sense of worth currently seem to depend on?"}, {"id": "f1", "type": "textarea", "label": "What happens to your worth when that thing dips or disappears?"}, {"id": "f2", "type": "textarea", "label": "What would you rather your worth be grounded in?"}, {"id": "f3", "type": "textarea", "label": "One way to practice grounding worth there this week"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('compliment-deflection-log', 'Compliment Deflection Log', 'cbt'::resource_kind, 'Tracks moments a client deflected or dismissed a compliment, and practices simply accepting it instead.', 'Use it to interrupt the automatic habit of arguing with positive feedback.', array['Adults', 'Teens']::text[], 'Ongoing', 'Deflecting a compliment — ‘oh, it was nothing,’ ‘anyone could have done it’ — can become so automatic that a client stops registering positive feedback at all. The log tracks compliments received, the automatic deflection, and a practiced alternative response of simply saying thank you without qualifying it. Even a client who does not believe the compliment yet can practice the behavior of accepting it.', '[{"id": "f0", "type": "textarea", "label": "The compliment you received"}, {"id": "f1", "type": "textarea", "label": "What did you automatically say or think?"}, {"id": "f2", "type": "textarea", "label": "What would ‘just saying thank you’ have sounded like?"}, {"id": "f3", "type": "textarea", "label": "Did you practice accepting it this week? What happened?"}]'::jsonb, array['self-esteem', 'self-criticism', 'core CBT']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('self-as-context-strengths-practice', 'Self-As-Context Strengths Practice', 'act'::resource_kind, 'Uses the observing-self perspective to notice a harsh self-verdict without becoming fused with it.', 'Use it to give a client distance from a self-critical verdict by practicing the observer’s view.', array['Adults', 'Teens']::text[], '15 minutes', 'The part of a person that notices a thought is not the same as the thought itself — the observing self watching ‘I’m worthless’ is not, itself, worthless. The client practices stepping back to that observer position when a harsh self-verdict shows up, noticing the verdict rather than being it. This is a stance to practice repeatedly, not a one-time insight that resolves the verdict.', '[{"id": "f0", "type": "textarea", "label": "The self-verdict that showed up"}, {"id": "f1", "type": "textarea", "label": "From the observer’s seat, what do you notice about having this thought?"}, {"id": "f2", "type": "textarea", "label": "Is the observer the same thing as the verdict, or something that notices it?"}, {"id": "f3", "type": "textarea", "label": "What changed, stepping back to notice rather than agreeing?"}]'::jsonb, array['self-esteem', 'self-as-context', 'defusion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('kindness-toward-myself-mirror-craft', 'Kindness Toward Myself Mirror Craft', 'kids'::resource_kind, 'A child decorates a mirror frame with kind phrases to read to themselves, practiced daily with a parent.', 'Use it to build a habit of self-kindness through repetition, before a child can explain why it matters.', array['Children']::text[], '15 minutes', 'The child chooses a few kind phrases — ‘I am learning,’ ‘mistakes are okay,’ ‘I am proud of me’ — and decorates a small mirror frame or card with them, placing it somewhere they will see it daily, like a bathroom mirror. The parent practices saying the phrases along with the child at first, since children often need to hear kindness modeled before they can offer it to themselves.', '[{"id": "f0", "type": "textarea", "label": "What kind phrases did you pick?"}, {"id": "f1", "type": "textarea", "label": "Where will you keep your mirror or card?"}, {"id": "f2", "type": "textarea", "label": "Did you say your phrases today? How did it feel?"}, {"id": "f3", "type": "textarea", "label": "Parent: did you practice saying them together?"}]'::jsonb, array['self-esteem', 'children', 'self-compassion']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-strength', 'Two Truths and a Strength', 'game'::resource_kind, 'A group icebreaker where each person shares two true strengths and one exaggerated one for others to guess.', 'Use it to get a group naming their own strengths out loud in a low-pressure, playful format.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Each player shares three statements about their own strengths, two true and one exaggerated, and the group guesses which is the stretch. Naming strengths about oneself can feel uncomfortable for a group working on self-esteem, and the playful framing lowers that discomfort enough that most people can do it without much hesitation. Debrief what it felt like to claim a strength out loud.', '[{"id": "f0", "type": "textarea", "label": "Your two true strengths"}, {"id": "f1", "type": "textarea", "label": "Your one exaggerated strength"}, {"id": "f2", "type": "textarea", "label": "What did the group guess, and did they get it right?"}, {"id": "f3", "type": "textarea", "label": "What was it like to say a real strength about yourself?"}]'::jsonb, array['self-esteem', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('social-safety-behaviors-checklist', 'Social Safety Behaviors Checklist', 'worksheet'::resource_kind, 'Lists the subtle safety behaviors a client uses in social situations, as targets to gradually drop.', 'Use it to name the small self-protective habits that quietly keep social anxiety in place.', array['Adults', 'Teens']::text[], '20 minutes', 'Safety behaviors in social anxiety are often subtle enough to go unnoticed — rehearsing a line beforehand, avoiding eye contact, over-explaining, gripping a drink to look occupied. Each one feels protective but also prevents the client from learning the situation would have gone fine without it. The client lists their own behaviors and picks one to drop, on purpose, in a low-stakes situation first.', '[{"id": "f0", "type": "textarea", "label": "Safety behaviors you use in social situations"}, {"id": "f1", "type": "textarea", "label": "Which one feels hardest to drop?"}, {"id": "f2", "type": "textarea", "label": "Pick one low-stakes situation to try dropping it"}, {"id": "f3", "type": "textarea", "label": "What happened when you dropped it?"}]'::jsonb, array['social anxiety', 'safety behaviors', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-check', 'Spotlight Effect Check', 'cbt'::resource_kind, 'Tests the belief that others notice a client’s mistakes or anxiety as much as it feels like they do.', 'Use it to gather evidence against the assumption that everyone is watching as closely as it feels.', array['Adults', 'Teens']::text[], '15 minutes', 'Social anxiety tends to inflate how much other people are actually noticing — a mistake that feels glaring to the person who made it is often missed entirely by everyone else, who are usually thinking about themselves. The client predicts how many people will notice a small slip before a situation, then checks afterward what evidence there actually was that anyone did.', '[{"id": "f0", "type": "textarea", "label": "The situation and the slip you are worried about"}, {"id": "f1", "type": "textarea", "label": "Prediction: how many people will notice?"}, {"id": "f2", "type": "textarea", "label": "What actually happened — any evidence anyone noticed?"}, {"id": "f3", "type": "textarea", "label": "What does the gap between prediction and evidence tell you?"}]'::jsonb, array['social anxiety', 'thinking traps', 'behavioral experiment']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('give-skills-social-practice-card', 'GIVE Skills Social Practice Card', 'dbt'::resource_kind, 'Adapts the DBT GIVE skill into a short script for practicing one low-stakes social interaction at a time.', 'Use it to pair an interpersonal skill with graded social exposure instead of avoiding the interaction entirely.', array['Adults', 'Teens']::text[], '15 minutes', 'GIVE, being gentle, showing interest, validating, and using an easy manner, gives a client something concrete to focus on that is not their own anxiety symptoms. The card pairs one GIVE element with a specific low-stakes interaction to try this week, shifting attention outward onto the skill rather than inward onto self-monitoring, which tends to fuel the anxiety further.', '[{"id": "f0", "type": "textarea", "label": "The low-stakes interaction you will practice"}, {"id": "f1", "type": "textarea", "label": "Which GIVE element will you focus on?"}, {"id": "f2", "type": "textarea", "label": "What did you notice about your anxiety during it?"}, {"id": "f3", "type": "textarea", "label": "How did focusing on the skill change where your attention went?"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('one-new-hello-chart', 'One New Hello Chart', 'kids'::resource_kind, 'A daily chart where a child tracks saying hello to just one person, building social approach one small step at a time.', 'Use it to build social approach skill gradually, starting from the smallest possible step.', array['Children']::text[], 'Ongoing', 'For a socially anxious child, a whole conversation can feel out of reach, but saying one hello usually does not. The chart tracks just that, one hello to one person a day, checked off with a sticker, without any pressure for the interaction to go further. Small, repeated wins build a track record the child can point to, which matters more than any single successful conversation.', '[{"id": "f0", "type": "textarea", "label": "Who did you say hello to today?"}, {"id": "f1", "type": "textarea", "label": "What did that feel like before you did it?"}, {"id": "f2", "type": "textarea", "label": "What did it feel like after?"}, {"id": "f3", "type": "textarea", "label": "Parent: sticker earned — yes or no?"}]'::jsonb, array['social anxiety', 'children', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('icebreaker-ladder-game', 'Icebreaker Ladder Game', 'game'::resource_kind, 'A group game climbing from very low-stakes to slightly harder icebreaker questions, one rung at a time.', 'Use it to practice graded social exposure inside a group in a structured, predictable format.', array['Groups', 'Teens']::text[], '20 minutes', 'Questions start as low-stakes as possible, a favorite color, a favorite food, and climb gradually toward slightly more personal ones as the group warms up, giving socially anxious members a predictable, low-pressure ramp instead of an unpredictable jump straight into deep sharing. Anyone can pass on a rung and try it again later, which keeps the exposure graded rather than forced.', '[{"id": "f0", "type": "textarea", "label": "Which rung did you find hardest?"}, {"id": "f1", "type": "textarea", "label": "Did you pass on any question, and try it again later?"}, {"id": "f2", "type": "textarea", "label": "What helped you answer as the questions got more personal?"}, {"id": "f3", "type": "textarea", "label": "What did you notice about the group as the game went on?"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('grief-anniversary-planning-sheet', 'Grief Anniversary Planning Sheet', 'worksheet'::resource_kind, 'Plans ahead for an anniversary, holiday or other date that tends to bring grief back to the surface.', 'Use it so a hard date is met with a plan instead of arriving unprepared.', array['Adults', 'Teens']::text[], '20 minutes', 'Anniversaries, birthdays and holidays after a loss often hit harder than expected, even when the date has been circled on the calendar for weeks. The client plans ahead of time what they want the day to include — a ritual, time alone, company, avoiding a particular place — rather than deciding in the moment when grief may already be running the day.', '[{"id": "f0", "type": "textarea", "label": "The upcoming date and what it marks"}, {"id": "f1", "type": "textarea", "label": "What do you want this day to include?"}, {"id": "f2", "type": "textarea", "label": "What do you want to avoid on this day?"}, {"id": "f3", "type": "textarea", "label": "Who, if anyone, do you want with you?"}]'::jsonb, array['grief and loss', 'planning', 'anniversary reactions']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('grief-guilt-thought-record', 'Grief Guilt Thought Record', 'cbt'::resource_kind, 'A thought record built around the guilt thoughts that often follow a loss, tested the same as any other.', 'Use it to examine grief-related guilt thoughts with the same rigor as any other automatic thought.', array['Adults', 'Teens']::text[], '20 minutes', '‘I should have called more’ or ‘I could have caught it sooner’ are common after a loss and rarely get examined the way an anxious thought would, because guilt can feel like proof of love rather than a thought worth questioning. The client logs the guilt thought, the evidence for and against it, and a more balanced version, treating it as a thought like any other.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f2", "type": "textarea", "label": "Evidence against it"}, {"id": "f3", "type": "textarea", "label": "A more balanced version of the thought"}]'::jsonb, array['grief and loss', 'guilt', 'thinking traps']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('carrying-it-forward-practice', 'Carrying It Forward Practice', 'act'::resource_kind, 'An acceptance practice for carrying grief forward alongside continued values-based living, not instead of it.', 'Use it to counter the belief that moving toward life again means leaving grief, or the person, behind.', array['Adults', 'Teens']::text[], '20 minutes', 'Grief and continuing to live do not have to trade off against each other, though it can feel that way, as if enjoying something again is a kind of forgetting. The client practices naming both at once: the loss that is still carried, and one values-based action taken anyway, in the same breath. The aim is not resolution but making room for both to be true together.', '[{"id": "f0", "type": "textarea", "label": "What are you still carrying from this loss?"}, {"id": "f1", "type": "textarea", "label": "A value that still matters to you"}, {"id": "f2", "type": "textarea", "label": "One action in that direction you could take, carrying the loss with you"}, {"id": "f3", "type": "textarea", "label": "What comes up when you imagine doing both at once?"}]'::jsonb, array['grief and loss', 'acceptance', 'values']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('grieving-differently-together-sheet', 'Grieving Differently Together Sheet', 'couples'::resource_kind, 'Helps a couple grieving the same loss understand why they are grieving in different ways and on different timelines.', 'Use it to stop divergent grieving styles from being read as one partner caring less.', array['Couples']::text[], '30 minutes', 'Two people grieving the same loss rarely grieve identically — one partner may want to talk often, the other may need quiet or activity, and each can misread the other’s style as not caring enough. Each partner describes their own grieving style and what they need from the other, and both name one thing they can stop assuming about the other’s grief once they hear this.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how does your grief usually show up?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what do you need from your partner right now?"}, {"id": "f2", "type": "textarea", "label": "Partner B: how does your grief usually show up?"}, {"id": "f3", "type": "textarea", "label": "Partner B: what do you need from your partner right now?"}, {"id": "f4", "type": "textarea", "label": "One assumption about each other’s grief you are ready to drop"}]'::jsonb, array['grief and loss', 'relationship issues', 'support']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('feelings-about-goodbye-storybook-craft', 'Feelings About Goodbye Storybook Craft', 'kids'::resource_kind, 'A child makes a simple illustrated booklet about their loss, in their own words and pictures, with a parent nearby.', 'Use it to give a child a concrete, contained way to tell their own story about the loss, at their own pace.', array['Children']::text[], 'Ongoing', 'Children often process loss in pieces rather than one conversation, and a small illustrated booklet gives them somewhere to put those pieces over time rather than needing to say everything at once. The parent stays nearby to help with words but lets the child lead the pictures and the pace, adding pages over days or weeks rather than finishing in one sitting.', '[{"id": "f0", "type": "textarea", "label": "What happened, in your own words or pictures"}, {"id": "f1", "type": "textarea", "label": "What you miss most"}, {"id": "f2", "type": "textarea", "label": "A happy memory to include"}, {"id": "f3", "type": "textarea", "label": "Who helps you when you feel sad about it"}]'::jsonb, array['grief and loss', 'children', 'narrative']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('relationship-pattern-history-sheet', 'Relationship Pattern History Sheet', 'worksheet'::resource_kind, 'Has a client trace a recurring relationship pattern across several relationships, not just the current one.', 'Use it to show a client a pattern is theirs to work on, not just a feature of one difficult partner.', array['Adults']::text[], '30 minutes', 'A pattern that shows up across several relationships, always the one who chases, always drawn to someone unavailable, always the one who goes quiet first, is more useful to examine than one blamed entirely on the current partner. The client lists past and current relationships and marks where the pattern shows up in each, then considers what role they tend to play in keeping it going.', '[{"id": "f0", "type": "textarea", "label": "The pattern you keep noticing"}, {"id": "f1", "type": "textarea", "label": "Where did it show up in past relationships?"}, {"id": "f2", "type": "textarea", "label": "Where does it show up now?"}, {"id": "f3", "type": "textarea", "label": "What is your part in keeping the pattern going?"}]'::jsonb, array['relationship issues', 'pattern', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-for-relationships', 'Mind-Reading Check for Relationships', 'cbt'::resource_kind, 'Tests an assumption about a partner’s thoughts or intentions against what they actually said when asked.', 'Use it to interrupt the habit of assuming a partner’s intent instead of checking it directly.', array['Adults']::text[], 'Ongoing', '‘They didn’t text back because they’re losing interest’ is a guess dressed up as a fact, and relationships absorb a lot of friction from guesses like it going unchecked. The client writes the assumption, rates how certain they feel, then actually asks the partner and logs the real answer. Comparing the guess to the answer over a few entries usually reveals how often the guess was simply wrong.', '[{"id": "f0", "type": "textarea", "label": "The assumption about your partner’s thoughts or intent"}, {"id": "f1", "type": "textarea", "label": "How certain did you feel, 0 to 100 percent?"}, {"id": "f2", "type": "textarea", "label": "What did they actually say when you asked?"}, {"id": "f3", "type": "textarea", "label": "How far off was the assumption?"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('committed-relationship-values-check', 'Committed Relationship Values Check', 'act'::resource_kind, 'Practices willingness to sit with discomfort, an awkward conversation, being vulnerable, in service of the relationship.', 'Use it when avoiding discomfort is quietly costing a client the relationship closeness they say they want.', array['Adults']::text[], '15 minutes', 'Avoiding an awkward conversation or staying guarded to sidestep discomfort often costs more closeness than the discomfort itself would have. The client names a relationship value, honesty, closeness, repair, and one uncomfortable action that would actually serve it, then practices willingness to feel the discomfort rather than waiting for it to go away first.', '[{"id": "f0", "type": "textarea", "label": "A relationship value that matters to you"}, {"id": "f1", "type": "textarea", "label": "What uncomfortable action would actually serve it?"}, {"id": "f2", "type": "textarea", "label": "What discomfort shows up when you imagine doing it?"}, {"id": "f3", "type": "textarea", "label": "Are you willing to feel that, in service of the value?"}]'::jsonb, array['relationship issues', 'values', 'willingness']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('relationship-check-the-facts-sheet', 'Relationship Check the Facts Sheet', 'dbt'::resource_kind, 'Applies DBT’s check the facts skill to a relationship conflict interpretation before reacting to it.', 'Use it to test whether a reaction to a partner’s words actually fits the facts of what was said.', array['Adults']::text[], '15 minutes', 'An emotional reaction to a partner’s comment sometimes fits the facts and sometimes runs ahead of them, shaped by past hurts more than the present moment. The client writes exactly what was said, their interpretation of it, and the emotion that followed, then checks whether the interpretation is the only one that fits the actual words. Where it does not, a different response usually becomes available.', '[{"id": "f0", "type": "textarea", "label": "What was actually said, word for word if possible"}, {"id": "f1", "type": "textarea", "label": "Your interpretation of it"}, {"id": "f2", "type": "textarea", "label": "The emotion that followed, and its intensity"}, {"id": "f3", "type": "textarea", "label": "Is your interpretation the only one that fits the facts?"}]'::jsonb, array['relationship issues', 'check the facts', 'emotion regulation']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('repeated-argument-autopsy', 'Repeated Argument Autopsy', 'couples'::resource_kind, 'Has a couple analyze the structure of a recurring argument, how it starts, escalates and ends, rather than its content.', 'Use it to interrupt a recurring argument’s pattern once both partners can see its shape.', array['Couples']::text[], '30 minutes', 'The same argument often repeats not because the topic keeps changing but because the structure never does, a familiar opening line, a predictable escalation, the same ending. Each partner separately describes the pattern’s stages, then the two compare notes and name the exact moment where a different move could change the outcome. Working on the structure tends to help more than re-litigating the last instance.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how does this argument usually start?"}, {"id": "f1", "type": "textarea", "label": "Partner B: how does this argument usually start?"}, {"id": "f2", "type": "textarea", "label": "How does it usually escalate, and how does it usually end?"}, {"id": "f3", "type": "textarea", "label": "Where is the one moment a different move could change it?"}]'::jsonb, array['relationship issues', 'conflict', 'pattern']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('safety-signal-card', 'Safety Signal Card', 'worksheet'::resource_kind, 'A card naming a client’s own signals of safety in the present, built for quick reference during distress.', 'Use it to give a client something concrete pointing to present safety, ready before it is needed.', array['Adults', 'Teens']::text[], '15 minutes', 'Built on a calm day, the card lists specific, personal signals that the present is safe — a locked door, a trusted person’s number, a phrase that has worked before. It does not ask for any account of what happened; it works entirely in the present tense. If distress escalates toward a crisis, 988 (call or text) and the client’s own safety plan come next, not this card alone.', '[{"id": "f0", "type": "textarea", "label": "A place that feels safe to you right now"}, {"id": "f1", "type": "textarea", "label": "A person you can reach out to"}, {"id": "f2", "type": "textarea", "label": "A phrase or reminder that has helped before"}, {"id": "f3", "type": "textarea", "label": "Where will you keep this card?"}]'::jsonb, array['sexual abuse', 'safety planning', 'PTSD and trauma']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('self-blame-versus-responsibility-sheet', 'Self-Blame Versus Responsibility Sheet', 'cbt'::resource_kind, 'Separates a client’s self-blame from where responsibility actually sits, without needing the details of what happened.', 'Use it to loosen self-blame that has settled somewhere it does not belong.', array['Adults', 'Teens']::text[], '20 minutes', 'Self-blame after sexual abuse often attaches to choices the client made, what they wore, where they were, what they said, as though those choices caused the abuse. The client can name the self-blaming thought and test it against a simple question: who chose to cause harm? The exercise works without any account of the abuse itself; it stays with the thought, not the story.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought you carry"}, {"id": "f1", "type": "textarea", "label": "What choice does it blame you for?"}, {"id": "f2", "type": "textarea", "label": "Who actually chose to cause harm?"}, {"id": "f3", "type": "textarea", "label": "What would you say to someone else carrying this same blame?"}]'::jsonb, array['sexual abuse', 'self-blame', 'shame']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('reclaiming-choice-practice', 'Reclaiming Choice Practice', 'act'::resource_kind, 'Practices noticing small present-day choices a client has, to rebuild a sense of agency at their own pace.', 'Use it to rebuild a felt sense of choice in the present, without needing to revisit the past.', array['Adults', 'Teens']::text[], '15 minutes', 'Abuse involves choice being taken away, and rebuilding a felt sense of agency can matter as much as any other part of healing, entirely apart from processing what happened. The practice has the client notice small, real choices available right now, what to eat, when to rest, who to see, and name each one as evidence that choice is theirs again. No account of the abuse itself is needed for this to work.', '[{"id": "f0", "type": "textarea", "label": "A small choice you made today"}, {"id": "f1", "type": "textarea", "label": "How did it feel to notice it as your choice?"}, {"id": "f2", "type": "textarea", "label": "What is one more choice available to you this week?"}, {"id": "f3", "type": "textarea", "label": "What does having choice again mean to you?"}]'::jsonb, array['sexual abuse', 'acceptance', 'safety planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('body-safety-grounding-card', 'Body Safety Grounding Card', 'dbt'::resource_kind, 'A grounding sequence for the body-based distress that can follow sexual abuse, without revisiting any details.', 'Use it to bring the body back to a felt sense of safety when distress spikes.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Distress after sexual abuse can show up first in the body, tension, disconnection, a racing heart, before any thought is even named. The card walks through a short, body-based grounding sequence: feet on the floor, hands on a solid surface, a slow count of the breath. It works without any narrative content and can be practiced calm, in session, before it is needed elsewhere.', '[{"id": "f0", "type": "textarea", "label": "Where do you notice the distress in your body first?"}, {"id": "f1", "type": "textarea", "label": "Feet on the floor — what do you notice?"}, {"id": "f2", "type": "textarea", "label": "Hands on a solid surface — what do you notice?"}, {"id": "f3", "type": "textarea", "label": "Rate the distress before and after this sequence"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('trusted-grown-ups-map', 'Trusted Grown-Ups Map', 'kids'::resource_kind, 'A child maps the trusted grown-ups they could go to if something felt wrong or unsafe.', 'Use it to build a child’s concrete list of safe adults to turn to, before it is ever needed.', array['Children']::text[], '15 minutes', 'The child draws or names a small circle of trusted grown-ups, at home, at school, in the family, they could go to if something ever felt wrong or unsafe, without needing to describe any specific worry to complete the map. Clinician note: if a child discloses anything during this or any session, follow your setting’s mandated reporting duties promptly, before continuing any other work.', '[{"id": "f0", "type": "textarea", "label": "Draw or name your trusted grown-ups"}, {"id": "f1", "type": "textarea", "label": "How could you find each one if you needed to?"}, {"id": "f2", "type": "textarea", "label": "What could you say to a grown-up if something felt wrong?"}, {"id": "f3", "type": "textarea", "label": "Parent or caregiver: is this map somewhere the child can remember it?"}]'::jsonb, array['sexual abuse', 'children', 'safety planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('coping-skills-audit-by-situation', 'Coping Skills Audit by Situation', 'worksheet'::resource_kind, 'Sorts a client’s coping skills by which situations they actually work best in, rather than one skill for all.', 'Use it to match a coping skill to the situation instead of reaching for the same one every time.', array['Adults', 'Teens']::text[], '20 minutes', 'A skill that works well for a racing mind at 2am may do nothing for a tense conversation at work, and clients often keep reaching for the same familiar skill regardless of fit. The client sorts their current coping skills by situation type, physical activation, racing thoughts, interpersonal conflict, low energy, building a reference to pull from instead of one default.', '[{"id": "f0", "type": "textarea", "label": "Skills that help with physical activation (racing heart, tension)"}, {"id": "f1", "type": "textarea", "label": "Skills that help with racing or looping thoughts"}, {"id": "f2", "type": "textarea", "label": "Skills that help in interpersonal conflict"}, {"id": "f3", "type": "textarea", "label": "Skills that help on low-energy days"}, {"id": "f4", "type": "textarea", "label": "Which situation type do you have the fewest skills for?"}]'::jsonb, array['coping skills', 'self-monitoring', 'planning']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('workable-coping-sort', 'Workable Coping Sort', 'act'::resource_kind, 'Sorts coping behaviors into those that move a client toward their values and those that only move away from pain.', 'Use it to notice which coping strategies build a life a client wants, not just relieve a moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Two coping behaviors can both bring short-term relief while pointing in opposite directions, one toward a life the client actually wants, the other only away from discomfort with nothing gained. The client sorts a list of their current coping behaviors into these two columns and looks at which column they reach for most, then considers where one ‘away from’ behavior could shift toward a ‘toward’ one.', '[{"id": "f0", "type": "textarea", "label": "Coping behaviors that move you toward something you value"}, {"id": "f1", "type": "textarea", "label": "Coping behaviors that only move you away from discomfort"}, {"id": "f2", "type": "textarea", "label": "Which column do you reach for most?"}, {"id": "f3", "type": "textarea", "label": "One ‘away from’ behavior you could shift toward a value"}]'::jsonb, array['coping skills', 'values', 'workability']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('skills-chain-backup-plan', 'Skills Chain Backup Plan', 'dbt'::resource_kind, 'Plans a second and third coping skill in advance, in case the first choice does not work in the moment.', 'Use it so a client has a next move ready instead of stalling when the first skill falls short.', array['Adults', 'Teens']::text[], '15 minutes', 'A single coping plan can leave a client stuck if the first skill they reach for does not work in the moment, which can feel like the whole plan failing rather than one option not fitting. The client plans a short chain, first skill, then a backup, then a third, ahead of time, so there is always a next move ready rather than starting from scratch mid-distress.', '[{"id": "f0", "type": "textarea", "label": "Your first-choice skill for this kind of moment"}, {"id": "f1", "type": "textarea", "label": "Backup skill if the first one does not work"}, {"id": "f2", "type": "textarea", "label": "Third option if neither works"}, {"id": "f3", "type": "textarea", "label": "Which one did you actually end up using, and how far down the chain?"}]'::jsonb, array['coping skills', 'planning', 'distress tolerance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('calm-down-card-deck-craft', 'Calm-Down Card Deck Craft', 'kids'::resource_kind, 'A child illustrates a small deck of cards, one coping skill per card, to shuffle through when upset.', 'Use it to give a child a hands-on deck of options they made themselves and can physically shuffle through.', array['Children']::text[], 'Ongoing', 'The child draws one coping skill per card, blowing bubbles, squeezing a pillow, counting to ten, asking for a hug, building a small deck over several sessions. When upset, the child (or parent, at first) shuffles through the deck to pick one to try, which turns ‘use a coping skill’ into a concrete, game-like action instead of an abstract instruction to remember.', '[{"id": "f0", "type": "textarea", "label": "What coping skill is on today’s new card?"}, {"id": "f1", "type": "textarea", "label": "Draw a picture for it"}, {"id": "f2", "type": "textarea", "label": "Which card did you pick the last time you were upset?"}, {"id": "f3", "type": "textarea", "label": "Did it help? Parent: what did you notice?"}]'::jsonb, array['coping skills', 'children', 'self-soothing']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('skill-or-bluff', 'Skill or Bluff', 'game'::resource_kind, 'A guessing game where players describe a coping skill, real or invented, and the group votes on which it is.', 'Use it to review real coping skills while keeping the format playful and a little competitive.', array['Groups', 'Teens']::text[], '20 minutes', 'Each player describes a coping skill with a straight face, some real, some invented on the spot, and the group votes on whether it is genuine or a bluff, earning a point for a correct guess either way. The debrief sorts out which described skills were real and worth remembering, folding review into a game that plays more like a party game than a therapy exercise.', '[{"id": "f0", "type": "textarea", "label": "The skill you described — real or a bluff?"}, {"id": "f1", "type": "textarea", "label": "Did the group guess correctly?"}, {"id": "f2", "type": "textarea", "label": "Which real skills came up that you want to remember?"}, {"id": "f3", "type": "textarea", "label": "Which bluff skill was the funniest?"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('safe-zone-shrinking-map', 'Safe Zone Shrinking Map', 'worksheet'::resource_kind, 'Maps how a client’s everyday ‘safe zone’ of places and activities has shrunk as a specific fear grew.', 'Use it to show a client how much territory avoidance has quietly claimed, and pick one edge to push back.', array['Adults', 'Teens']::text[], '20 minutes', 'A specific phobia tends to expand its no-go zone gradually enough that a client stops noticing how much has been given up, avoiding driving on highways can end up limiting a job search; avoiding dogs can end up limiting which friends’ homes get visited. The client draws their current safe zone against what it used to include, then picks one edge of the shrunken territory to reclaim first.', '[{"id": "f0", "type": "textarea", "label": "What does your safe zone include today?"}, {"id": "f1", "type": "textarea", "label": "What did it used to include before the fear grew?"}, {"id": "f2", "type": "textarea", "label": "Which edge of the shrunken zone matters most to reclaim?"}, {"id": "f3", "type": "textarea", "label": "What would the first small step back into it look like?"}]'::jsonb, array['phobias', 'avoidance', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('feared-outcome-likelihood-sheet', 'Feared Outcome Likelihood Sheet', 'cbt'::resource_kind, 'Has a client estimate the real-world odds of their feared outcome, then compares it to base rates.', 'Use it to put a number on a feared outcome instead of letting it stay an unexamined certainty.', array['Adults', 'Teens']::text[], '15 minutes', 'A specific phobia often runs on an outcome that feels certain but is, in fact, rare, the plane will crash, the dog will bite, the elevator will get stuck. The client estimates their own odds, then the two of you look together at what is actually known about the base rate for that outcome. The gap between the felt certainty and the real odds becomes something concrete to work with.', '[{"id": "f0", "type": "textarea", "label": "The feared outcome"}, {"id": "f1", "type": "textarea", "label": "Your estimate of the odds it happens, in percent"}, {"id": "f2", "type": "textarea", "label": "What is actually known about the real odds?"}, {"id": "f3", "type": "textarea", "label": "How does that gap change how certain the fear feels?"}]'::jsonb, array['phobias', 'thinking traps', 'behavioral experiment']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('fear-passenger-exposure-log', 'Fear Passenger Exposure Log', 'act'::resource_kind, 'Logs approach steps toward a feared object or situation with fear allowed to come along, not required to leave first.', 'Use it to decouple doing the approach step from feeling calm enough to do it first.', array['Adults', 'Teens']::text[], '20 minutes', 'Waiting to feel calm before approaching a feared situation usually means waiting indefinitely, since the calm tends to arrive after repeated approach, not before it. The client logs each approach step alongside how much fear was present and whether they did the step anyway, treating the fear as an unwelcome passenger rather than a stop sign.', '[{"id": "f0", "type": "textarea", "label": "Today’s approach step"}, {"id": "f1", "type": "textarea", "label": "Fear level going in, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Did you do the step with the fear present?"}, {"id": "f3", "type": "textarea", "label": "What did the fear do during and after the step?"}]'::jsonb, array['phobias', 'acceptance', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('fear-ladder-sticker-chart', 'Fear Ladder Sticker Chart', 'kids'::resource_kind, 'A sticker chart tracking a child’s steps up their own fear ladder, one small approach step at a time.', 'Use it to make gradual progress up a fear ladder visible and rewarding for a child.', array['Children']::text[], 'Ongoing', 'Built together with the parent, the ladder breaks a specific fear into small graded steps, and each completed step earns a sticker on the chart. Progress up a fear ladder can feel invisible day to day, and the chart gives the child something to look back at and see how far they have actually climbed. Celebrate effort at each step, not only reaching the top.', '[{"id": "f0", "type": "textarea", "label": "Your fear ladder, from easiest to hardest step"}, {"id": "f1", "type": "textarea", "label": "Which step did you try today?"}, {"id": "f2", "type": "textarea", "label": "How scared were you before, and after?"}, {"id": "f3", "type": "textarea", "label": "Parent: sticker earned — yes or no?"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('fear-facts-quiz-show', 'Fear Facts Quiz Show', 'game'::resource_kind, 'A quiz game that corrects common myths about feared objects and situations, in a playful group format.', 'Use it to chip away at threat overestimation with real information, delivered as a game rather than a lecture.', array['Groups', 'Teens']::text[], '20 minutes', 'Questions test common beliefs about feared things, how likely a dog is to bite, how safe air travel actually is, how elevators are inspected, and players guess true or false before hearing the real answer. Presenting accurate information as a game rather than a lecture tends to land better with a group that already feels defensive about being told their fear is irrational.', '[{"id": "f0", "type": "textarea", "label": "Which question surprised you the most?"}, {"id": "f1", "type": "textarea", "label": "What did you believe before, and what is actually true?"}, {"id": "f2", "type": "textarea", "label": "Does this change how big the fear feels?"}, {"id": "f3", "type": "textarea", "label": "What is one question you would add to the quiz?"}]'::jsonb, array['phobias', 'group', 'play']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('body-talk-audit', 'Body Talk Audit', 'worksheet'::resource_kind, 'Tracks how often a client’s day includes appearance-focused talk or comparison, in conversation or media.', 'Use it to make an often-invisible daily habit of appearance talk visible and open to change.', array['Adults', 'Teens']::text[], 'One week', 'Appearance-focused comments, from others, in media, or self-directed, can run through a day almost unnoticed until they are tracked on purpose. The client logs each instance along with how it affected their mood, then looks for patterns: certain people, certain apps, certain times of day. The goal is awareness first; specific changes come once the pattern is visible.', '[{"id": "f0", "type": "textarea", "label": "The appearance-focused moment (conversation, media, self-talk)"}, {"id": "f1", "type": "textarea", "label": "Where did it come from?"}, {"id": "f2", "type": "textarea", "label": "How did it affect your mood?"}, {"id": "f3", "type": "textarea", "label": "What pattern are you noticing across entries?"}]'::jsonb, array['body image', 'self-monitoring', 'media literacy']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('appearance-comparison-interrupt-sheet', 'Appearance Comparison Interrupt Sheet', 'cbt'::resource_kind, 'Catches an automatic appearance comparison and tests the assumption behind it before it settles in.', 'Use it to interrupt an automatic comparison before it turns into a settled negative belief.', array['Adults', 'Teens']::text[], '15 minutes', 'A comparison, to a photo, a stranger, a past version of oneself, often happens in a split second and gets treated as a verdict rather than a passing thought. The client catches the comparison, writes the assumption behind it, and asks what is actually known instead of assumed. Slowing the moment down tends to loosen its grip more than trying to avoid comparisons altogether.', '[{"id": "f0", "type": "textarea", "label": "The comparison that came up"}, {"id": "f1", "type": "textarea", "label": "What assumption is behind it?"}, {"id": "f2", "type": "textarea", "label": "What do you actually know, versus assume?"}, {"id": "f3", "type": "textarea", "label": "What would you say to a friend having this same comparison?"}]'::jsonb, array['body image', 'thinking traps', 'self-monitoring']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('body-as-vehicle-practice', 'Body as Vehicle Practice', 'act'::resource_kind, 'Shifts attention from how the body looks to what it allows a client to do in service of their values.', 'Use it to widen a client’s relationship with their body beyond appearance alone.', array['Adults', 'Teens']::text[], '15 minutes', 'The body carries a person toward the things they value, a walk with a friend, picking up a child, standing at a job that matters, regardless of how it looks doing it. The client names a recent moment the body made a valued activity possible and practices noticing that function, not appearance, as what the moment was actually about. Repetition matters more than any single entry here.', '[{"id": "f0", "type": "textarea", "label": "A recent moment your body made something you value possible"}, {"id": "f1", "type": "textarea", "label": "What did your body let you do in that moment?"}, {"id": "f2", "type": "textarea", "label": "What would you have missed without it?"}, {"id": "f3", "type": "textarea", "label": "What does thanking your body for function, not appearance, feel like?"}]'::jsonb, array['body image', 'values', 'acceptance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('body-image-opposite-action-card', 'Body Image Opposite Action Card', 'dbt'::resource_kind, 'Applies the DBT opposite action skill to the urge to avoid or hide that body image distress often brings.', 'Use it to interrupt avoidance driven by body image distress before it narrows a client’s life further.', array['Adults', 'Teens']::text[], 'Ongoing', 'Body image distress often comes with an urge to avoid, skip the event, cancel the photo, stay home, that can quietly shrink a client’s life over time if it goes unexamined. The client names the urge, checks whether acting on it fits the actual situation, and practices the opposite action fully when it does not, going to the event rather than only partly showing up.', '[{"id": "f0", "type": "textarea", "label": "The situation and the urge to avoid or hide"}, {"id": "f1", "type": "textarea", "label": "Does the urge fit the actual situation?"}, {"id": "f2", "type": "textarea", "label": "The opposite action, described fully"}, {"id": "f3", "type": "textarea", "label": "What happened when you did the opposite action?"}]'::jsonb, array['body image', 'opposite action', 'avoidance']::text[], '2026-09-24T15:00:00+00:00'::timestamptz),
  ('body-image-support-conversation-guide', 'Body Image Support Conversation Guide', 'couples'::resource_kind, 'Helps a partner learn to support body image struggles without appearance-focused comments that can backfire.', 'Use it to replace well-meaning appearance comments with support that actually helps.', array['Couples']::text[], '20 minutes', 'A partner’s well-meant reassurance about appearance can land badly for someone struggling with body image, since it keeps the conversation centered on looks either way. The guide has the struggling partner describe what kind of support actually helps, distraction, a hug, a change of subject, and the other partner practices offering that instead of a compliment about appearance.', '[{"id": "f0", "type": "textarea", "label": "Struggling partner: what kind of support actually helps you?"}, {"id": "f1", "type": "textarea", "label": "Struggling partner: what comments, even kind ones, make it worse?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what will you try saying or doing instead?"}, {"id": "f3", "type": "textarea", "label": "How did it go the last time you tried this?"}]'::jsonb, array['body image', 'support', 'communication']::text[], '2026-09-24T15:00:00+00:00'::timestamptz)
